package com.combatlog;

import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import java.util.Objects;

public final class AttackRow
{
	private final List<HitRecord> hits = new ArrayList<>();

	private AttackRow(HitRecord hit)
	{
		hits.add(hit);
	}

	public List<HitRecord> getHits()
	{
		return Collections.unmodifiableList(hits);
	}

	public HitRecord first()
	{
		return hits.get(0);
	}

	public boolean isBlock()
	{
		for (HitRecord hit : hits)
		{
			if (!hit.isBlock())
			{
				return false;
			}
		}
		return true;
	}

	public boolean isSplash()
	{
		return first().isSplash();
	}

	public boolean isSpecial()
	{
		for (HitRecord hit : hits)
		{
			if (hit.isSpecial())
			{
				return true;
			}
		}
		if (hits.size() < 2)
		{
			return false;
		}
		Integer weapon = first().getWeaponItemId();
		return weapon != null && SpecWeapons.multiSpec(weapon);
	}

	public int getTotal()
	{
		int total = 0;
		for (HitRecord hit : hits)
		{
			if (!hit.isBlock())
			{
				total += hit.getAmount();
			}
		}
		return total;
	}

	public int getOverkill()
	{
		int overkill = 0;
		for (HitRecord hit : hits)
		{
			overkill += hit.getOverkill();
		}
		return overkill;
	}

	private boolean accepts(HitRecord hit)
	{
		HitRecord first = hits.get(0);
		if (first.isSplash() || hit.isSplash())
		{
			return false;
		}
		if (first.getDirection() != hit.getDirection() || first.getSource() != hit.getSource())
		{
			return false;
		}
		if (!Objects.equals(first.getFightId(), hit.getFightId()))
		{
			return false;
		}
		if (specBurst(first, hit))
		{
			return true;
		}
		if (first.getDirection() == DamageDirection.INCOMING)
		{
			return false;
		}
		// A zero from the same special stays on that row, even a couple of ticks later.
		if (first.isBlock() || hit.isBlock() || first.getAmount() <= 0 || hit.getAmount() <= 0)
		{
			return first.getAttackId() != null
				&& first.getAttackId().equals(hit.getAttackId())
				&& (first.isSpecial() || hit.isSpecial());
		}
		if (first.getAttackId() != null && first.getAttackId().equals(hit.getAttackId()))
		{
			return true;
		}
		return first.getAttackId() == null
			&& hit.getAttackId() == null
			&& first.getTick() > 0
			&& first.getTick() == hit.getTick()
			&& Objects.equals(first.getWeaponItemId(), hit.getWeaponItemId());
	}

	/**
	 * Hitsplats from one dragon-claw or dagger special, including a zero that
	 * lands a tick later. Daggers also hit twice on a normal swing, so those
	 * stay a normal row and only claws are labeled Spec.
	 */
	private static boolean specBurst(HitRecord first, HitRecord hit)
	{
		Integer weapon = first.getWeaponItemId();
		if (weapon == null || weapon <= 0 || !weapon.equals(hit.getWeaponItemId()))
		{
			return false;
		}
		if (first.getSource() != DamageSource.WEAPON || hit.getSource() != DamageSource.WEAPON)
		{
			return false;
		}
		int window = SpecWeapons.burst(weapon);
		if (window <= 0 || first.getTick() <= 0 || hit.getTick() <= 0)
		{
			return false;
		}
		if (Math.abs(hit.getTick() - first.getTick()) > window)
		{
			return false;
		}
		if (first.isSpecial() || hit.isSpecial() || first.getDirection() == DamageDirection.INCOMING)
		{
			return true;
		}
		return SpecWeapons.multiSpec(weapon);
	}

	private void add(HitRecord hit)
	{
		hits.add(hit);
	}

	public static List<AttackRow> group(List<HitRecord> hits)
	{
		List<HitRecord> ordered = new ArrayList<>(hits);
		ordered.sort(Comparator.comparingInt(HitRecord::getSequence).thenComparingLong(HitRecord::getTimeMillis));
		List<AttackRow> rows = new ArrayList<>();
		for (HitRecord hit : ordered)
		{
			AttackRow match = null;
			for (int i = rows.size() - 1; i >= 0; i--)
			{
				if (rows.get(i).accepts(hit))
				{
					match = rows.get(i);
					break;
				}
			}
			if (match != null)
			{
				match.add(hit);
			}
			else
			{
				rows.add(new AttackRow(hit));
			}
		}
		Collections.reverse(rows);
		return rows;
	}

	public static int countWeaponAttacks(List<HitRecord> hits)
	{
		int attacks = 0;
		for (AttackRow row : group(hits))
		{
			HitRecord first = row.first();
			if (first.getDirection() == DamageDirection.OUTGOING && first.getSource() == DamageSource.WEAPON && !row.isBlock() && !row.isSplash())
			{
				attacks++;
			}
		}
		return attacks;
	}
}

package com.combatlog;

import javax.annotation.Nullable;

public final class AttackSwing
{
	private final int tick;
	@Nullable
	private final Integer npcIndex;
	private final String name;
	@Nullable
	private final Integer weaponItemId;
	private final int speed;
	private final long attackId;
	private final boolean spec;

	public AttackSwing(int tick, @Nullable Integer npcIndex, String name, @Nullable Integer weaponItemId, int speed, long attackId)
	{
		this(tick, npcIndex, name, weaponItemId, speed, attackId, false);
	}

	private AttackSwing(int tick, @Nullable Integer npcIndex, String name, @Nullable Integer weaponItemId, int speed, long attackId, boolean spec)
	{
		this.tick = tick;
		this.npcIndex = npcIndex;
		this.name = name == null ? "" : Names.plain(name);
		this.weaponItemId = weaponItemId;
		this.speed = speed > 0 ? speed : 4;
		this.attackId = attackId;
		this.spec = spec;
	}

	public int getTick()
	{
		return tick;
	}

	@Nullable
	public Integer getNpcIndex()
	{
		return npcIndex;
	}

	public String getName()
	{
		return name;
	}

	@Nullable
	public Integer getWeaponItemId()
	{
		return weaponItemId;
	}

	public int getSpeed()
	{
		return speed;
	}

	public long getAttackId()
	{
		return attackId;
	}

	public boolean isSpec()
	{
		return spec;
	}

	public AttackSwing withWeapon(@Nullable Integer weaponItemId, int speed)
	{
		return new AttackSwing(tick, npcIndex, name, weaponItemId, speed, attackId, spec);
	}

	public AttackSwing withSpec()
	{
		return new AttackSwing(tick, npcIndex, name, weaponItemId, speed, attackId, true);
	}
}

package com.combatlog;

import java.util.Locale;
import javax.annotation.Nullable;
import net.runelite.api.gameval.NpcID;

/**
 * Combat dummy pictures use the same hosted icon set as other NPCs. Every
 * dummy variant shares the basic dummy's id so one file covers them.
 */
final class CombatDummy
{
	static final int ICON_ID = NpcID.POH_COMBAT_DUMMY_NPC;

	private CombatDummy()
	{
	}

	static int iconId(int npcId)
	{
		return isDummy(npcId) ? ICON_ID : npcId;
	}

	static boolean isDummy(int npcId)
	{
		switch (npcId)
		{
			case NpcID.POH_COMBAT_DUMMY_NPC:
			case NpcID.POH_COMBAT_DUMMY_UNDEADSLAYER_NPC:
			case NpcID.POH_COMBAT_DUMMY_UPGRADED_NPC:
			case NpcID.POH_COMBAT_DUMMY_UPGRADED_UNDEADSLAYER_NPC:
			case NpcID.POH_COMBAT_DUMMY_UPGRADED_ETHER_NPC:
			case NpcID.POH_COMBAT_DUMMY_UPGRADED_KQ_NPC:
			case NpcID.POH_COMBAT_DUMMY_UPGRADED_KURASK_NPC:
			case NpcID.POH_COMBAT_DUMMY_UPGRADED_VAMPIRE_NPC:
			case NpcID.POH_COMBAT_DUMMY_UPGRADED_VORKATH_NPC:
			case NpcID.TEST_COMBAT_DUMMY:
			case NpcID.TEST_COMBAT_DUMMY_MAXHIT:
			case NpcID.TEST_COMBAT_DUMMY_2:
				return true;
			default:
				return false;
		}
	}

	static boolean named(@Nullable String name)
	{
		if (name == null)
		{
			return false;
		}
		String plain = name.trim().toLowerCase(Locale.ROOT);
		return "combat dummy".equals(plain) || plain.startsWith("combat dummy ");
	}
}

package com.combatlog;

import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.annotation.Nullable;
import javax.inject.Singleton;

@Singleton
public class CombatLog
{
	/**
	 * One game tick. DPS is withheld until a fight has lasted at least this
	 * long so the first hit does not report an enormous rate.
	 */
	static final long MIN_ELAPSED_MS = 600L;

	private final Object lock = new Object();
	private final FightTracker fights = new FightTracker();
	private List<HitRecord> hits = Collections.emptyList();
	private int maxEntries;
	private int version;

	public CombatLog()
	{
		this(300);
	}

	CombatLog(int maxEntries)
	{
		this.maxEntries = Math.max(1, maxEntries);
	}

	public void add(HitRecord record)
	{
		synchronized (lock)
		{
			HitRecord stored = fights.accept(record);
			if (stored == null)
			{
				return;
			}
			version++;
			List<HitRecord> next = new ArrayList<>(Math.min(hits.size() + 1, maxEntries));
			next.add(stored);
			int keep = maxEntries - 1;
			for (int i = 0; i < hits.size() && i < keep; i++)
			{
				next.add(hits.get(i));
			}
			for (int i = keep; i < hits.size(); i++)
			{
				fights.forget(hits.get(i));
			}
			hits = Collections.unmodifiableList(next);
			if (hits.size() > keep)
			{
				// The list is not strictly in tick order, so keep a little before the oldest tick.
				int oldest = oldestTick(hits);
				if (oldest > 0)
				{
					fights.pruneTicksBefore(oldest - 2);
				}
			}
		}
	}

	@Nullable
	public Integer currentNpc(@Nullable Integer npcIndex, int tick)
	{
		synchronized (lock)
		{
			return fights.currentNpc(npcIndex, tick);
		}
	}

	public void closeLife(@Nullable Integer npcIndex, int tick)
	{
		synchronized (lock)
		{
			version++;
			fights.closeLife(npcIndex, tick);
		}
	}

	public void closeQuiet(@Nullable Integer npcIndex, int tick)
	{
		synchronized (lock)
		{
			version++;
			fights.closeQuiet(npcIndex, tick);
		}
	}

	public void closeAllQuiet(int tick)
	{
		synchronized (lock)
		{
			version++;
			fights.closeAllQuiet(tick);
		}
	}

	public void noteForm(@Nullable Integer npcIndex, int npcId)
	{
		synchronized (lock)
		{
			version++;
			fights.noteForm(npcIndex, npcId);
		}
	}

	public void noteMaxHp(@Nullable Integer npcIndex, int maxHp)
	{
		synchronized (lock)
		{
			version++;
			fights.noteMaxHp(npcIndex, maxHp);
		}
	}

	public void noteDelve(@Nullable Integer npcIndex, int level)
	{
		synchronized (lock)
		{
			version++;
			fights.noteDelve(npcIndex, level);
		}
	}

	public void joinDoomSurface(@Nullable Integer npcIndex, int level)
	{
		synchronized (lock)
		{
			fights.joinDoomSurface(npcIndex, level);
		}
	}

	public void resumeDoomSurface(int tick)
	{
		synchronized (lock)
		{
			fights.resumeDoomSurface(tick);
		}
	}

	public boolean hasOpenDoomSurface()
	{
		synchronized (lock)
		{
			return fights.hasOpenDoomSurface();
		}
	}

	public boolean foldDoom()
	{
		synchronized (lock)
		{
			if (!fights.foldDoomLevels())
			{
				return false;
			}
			version++;
			return true;
		}
	}

	public void finishDoomSurface(int tick, boolean killed)
	{
		synchronized (lock)
		{
			version++;
			fights.finishDoomSurface(tick, killed);
		}
	}

	public void noteAttack(int tick, @Nullable Integer npcIndex, String name, @Nullable Integer weaponItemId, int speed)
	{
		synchronized (lock)
		{
			version++;
			fights.noteAttack(new AttackSwing(tick, npcIndex, name, weaponItemId, speed, 0));
		}
	}

	/**
	 * Doom's melee charge is open from {@code startTick} through {@code untilTick}.
	 * Hitsplats of {@code bonus} in that window are the punish.
	 */
	public void notePunish(int npcIndex, int startTick, int untilTick, int bonus)
	{
		synchronized (lock)
		{
			version++;
			fights.notePunish(npcIndex, startTick, untilTick, bonus);
		}
	}

	public void clearPunish()
	{
		synchronized (lock)
		{
			version++;
			fights.clearPunish();
		}
	}

	/** The attack on this tick spent special attack energy. Its hitsplats are the spec. */
	public void markSpecSwing(int tick, @Nullable Integer npcIndex)
	{
		synchronized (lock)
		{
			version++;
			fights.markSpecSwing(tick, npcIndex);
		}
	}

	public void noteAttack(AttackSwing swing)
	{
		synchronized (lock)
		{
			version++;
			fights.noteAttack(swing);
		}
	}

	@Nullable
	public Integer weaponFor(@Nullable Integer npcIndex, int tick, @Nullable Integer equipped)
	{
		synchronized (lock)
		{
			return fights.weaponFor(npcIndex, tick, equipped);
		}
	}

	public void retargetWeapon(int tick, @Nullable Integer npcIndex, int weaponItemId, int speed)
	{
		synchronized (lock)
		{
			version++;
			fights.retargetWeapon(tick, npcIndex, weaponItemId, speed);
		}
	}

	public boolean hasRecentAttack(@Nullable Integer npcIndex, int tick)
	{
		synchronized (lock)
		{
			return fights.hasRecentAttack(npcIndex, tick);
		}
	}

	/**
	 * Poison, venom, and burn on a player count only while you are fighting
	 * that player. Those splats are visible for anyone's poison.
	 */
	public boolean fightingPlayer(@Nullable String name, int tick)
	{
		synchronized (lock)
		{
			return fights.fightingPlayer(name, tick);
		}
	}

	@Nullable
	public String soleOpenPlayer()
	{
		synchronized (lock)
		{
			return fights.soleOpenPlayer();
		}
	}

	public void notePlayerHead(@Nullable String name, int itemId)
	{
		notePlayerHead(name, itemId, null);
	}

	public void notePlayerHead(@Nullable String name, int itemId, @Nullable String itemName)
	{
		synchronized (lock)
		{
			version++;
			fights.notePlayerHead(name, itemId, itemName);
		}
	}

	public void noteCombatTick(int tick)
	{
		synchronized (lock)
		{
			version++;
			fights.noteCombatTick(tick);
		}
	}

	public void clear()
	{
		synchronized (lock)
		{
			version++;
			hits = Collections.emptyList();
			fights.clear();
		}
	}

	public void removeFight(long fightId)
	{
		synchronized (lock)
		{
			version++;
			List<HitRecord> next = new ArrayList<>();
			for (HitRecord hit : hits)
			{
				if (hit.getFightId() == null || hit.getFightId() != fightId)
				{
					next.add(hit);
				}
			}
			hits = Collections.unmodifiableList(next);
			fights.remove(fightId);
		}
	}

	public void setMaxEntries(int maxEntries)
	{
		synchronized (lock)
		{
			version++;
			this.maxEntries = Math.max(1, maxEntries);
			if (hits.size() > this.maxEntries)
			{
				for (int i = this.maxEntries; i < hits.size(); i++)
				{
					fights.forget(hits.get(i));
				}
				hits = Collections.unmodifiableList(new ArrayList<>(hits.subList(0, this.maxEntries)));
			}
		}
	}

	/**
	 * Changes whenever the log or its fights change, so a caller can reuse a
	 * snapshot until it does. Time based fields still need a fresh summary.
	 */
	public int version()
	{
		synchronized (lock)
		{
			return version;
		}
	}

	public CombatSnapshot summarize(long nowMillis, int recentSeconds)
	{
		return summarize(nowMillis, recentSeconds, DamageView.OUTGOING);
	}

	public CombatSnapshot summarize(long nowMillis, int recentSeconds, DamageView view)
	{
		List<HitRecord> current;
		List<Fight> fightList;
		int activeTicks;
		int nowTick;
		synchronized (lock)
		{
			current = hits;
			fightList = fights.fights();
			nowTick = fights.getLastTick();
			activeTicks = fights.activeTickCount(oldestTick(current));
		}

		DamageView shown = view == null ? DamageView.OUTGOING : view;
		if (current.isEmpty())
		{
			return CombatSnapshot.empty(shown);
		}

		int windowSeconds = Math.max(1, recentSeconds);
		long recentCutoff = nowMillis - windowSeconds * 1000L;

		long weaponDamage = 0;
		long overkill = 0;
		long damageTaken = 0;
		int blocks = 0;
		int incomingHits = 0;
		int maxHit = 0;
		long firstDamageTime = Long.MAX_VALUE;
		long recentDamage = 0;

		Map<TargetKey, MutableTarget> byTarget = new HashMap<>();
		for (HitRecord hit : current)
		{
			if (hit.getDirection() == DamageDirection.INCOMING)
			{
				if (!hit.isMiss())
				{
					damageTaken += hit.getAmount();
					incomingHits++;
				}
				continue;
			}

			TargetKey key = new TargetKey(hit.getTargetName(), hit.getTargetKind());
			MutableTarget target = byTarget.get(key);
			if (target == null)
			{
				target = new MutableTarget(hit.getTargetName(), hit.getTargetKind());
				byTarget.put(key, target);
			}

			if (hit.isMiss())
			{
				if (hit.getSource() == DamageSource.WEAPON)
				{
					blocks++;
					target.blocks++;
				}
				continue;
			}

			if (!hit.countsTowardWeaponDamage())
			{
				continue;
			}

			weaponDamage += hit.getAmount();
			overkill += hit.getOverkill();
			target.damage += hit.getAmount();
			if (hit.getAmount() > maxHit)
			{
				maxHit = hit.getAmount();
			}
			if (hit.getAmount() > target.maxHit)
			{
				target.maxHit = hit.getAmount();
			}
			if (hit.getTimeMillis() < firstDamageTime)
			{
				firstDamageTime = hit.getTimeMillis();
			}
			if (hit.getTimeMillis() >= recentCutoff)
			{
				recentDamage += hit.getAmount();
			}
		}

		int damageHits = AttackRow.countWeaponAttacks(current);
		for (MutableTarget target : byTarget.values())
		{
			target.hits = countTargetAttacks(current, target.name, target.kind);
		}

		Double average = damageHits == 0 ? null : weaponDamage / (double) damageHits;
		Double sessionDps = null;
		Double recentDps = null;
		long dpsDamage = Math.max(0, weaponDamage - overkill);
		if (activeTicks > 0 && dpsDamage > 0)
		{
			sessionDps = dpsDamage / (activeTicks * FightSummary.TICK_SECONDS);
		}
		else if (damageHits > 0)
		{
			long elapsed = nowMillis - firstDamageTime;
			if (elapsed >= MIN_ELAPSED_MS)
			{
				sessionDps = dpsDamage / (elapsed / 1000.0);
			}
		}
		if (damageHits > 0)
		{
			long elapsed = nowMillis - firstDamageTime;
			if (elapsed >= MIN_ELAPSED_MS)
			{
				long span = Math.min(windowSeconds * 1000L, elapsed);
				recentDps = recentDamage / (span / 1000.0);
			}
		}

		List<TargetTotal> targets = new ArrayList<>(byTarget.size());
		for (MutableTarget target : byTarget.values())
		{
			String pace = FightSummary.pace(fightList, target.name, target.kind);
			targets.add(new TargetTotal(target.name, target.kind, target.damage, target.hits, target.blocks, target.maxHit, pace));
		}
		targets.sort(Comparator.comparingLong(TargetTotal::getDamage).reversed()
			.thenComparing(Comparator.comparingInt(TargetTotal::getHits).reversed())
			.thenComparing(TargetTotal::getName));

		List<HitRecord> visible = new ArrayList<>();
		for (HitRecord hit : current)
		{
			if (hit.visibleIn(shown))
			{
				visible.add(hit);
			}
		}

		List<Fight> visibleFights = new ArrayList<>();
		for (Fight fight : fightList)
		{
			if (fight.visibleIn(shown))
			{
				visibleFights.add(fight);
			}
		}

		return new CombatSnapshot(
			Collections.unmodifiableList(visible),
			Collections.unmodifiableList(targets),
			Collections.unmodifiableList(visibleFights),
			weaponDamage,
			damageHits,
			blocks,
			maxHit,
			average,
			sessionDps,
			recentDps,
			damageTaken,
			incomingHits,
			shown,
			nowTick);
	}

	private static int oldestTick(List<HitRecord> hits)
	{
		for (int i = hits.size() - 1; i >= 0; i--)
		{
			if (hits.get(i).getTick() > 0)
			{
				return hits.get(i).getTick();
			}
		}
		return 0;
	}

	private static int countTargetAttacks(List<HitRecord> hits, String name, TargetKind kind)
	{
		List<HitRecord> matching = new ArrayList<>();
		for (HitRecord hit : hits)
		{
			if (hit.getTargetKind() == kind && name.equals(hit.getTargetName()))
			{
				matching.add(hit);
			}
		}
		return AttackRow.countWeaponAttacks(matching);
	}

	private static final class TargetKey
	{
		private final String name;
		private final TargetKind kind;

		private TargetKey(String name, TargetKind kind)
		{
			this.name = name;
			this.kind = kind;
		}

		@Override
		public boolean equals(Object other)
		{
			if (this == other)
			{
				return true;
			}
			if (!(other instanceof TargetKey))
			{
				return false;
			}
			TargetKey targetKey = (TargetKey) other;
			return kind == targetKey.kind && name.equals(targetKey.name);
		}

		@Override
		public int hashCode()
		{
			return 31 * name.hashCode() + kind.hashCode();
		}
	}

	private static final class MutableTarget
	{
		private final String name;
		private final TargetKind kind;
		private long damage;
		private int hits;
		private int blocks;
		private int maxHit;

		private MutableTarget(String name, TargetKind kind)
		{
			this.name = name;
			this.kind = kind;
		}
	}
}

