package com.combatlog;

import java.time.Instant;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import javax.annotation.Nullable;

public final class CombatLogFormatter
{
	private static final DateTimeFormatter TIME = DateTimeFormatter.ofPattern("HH:mm:ss");

	private CombatLogFormatter()
	{
	}

	public static String formatTime(long timeMillis, ZoneId zone)
	{
		return TIME.format(Instant.ofEpochMilli(timeMillis).atZone(zone));
	}

	public static int thrallDamage(Iterable<HitRecord> hits)
	{
		int total = 0;
		for (HitRecord hit : hits)
		{
			if (hit.getSource() == DamageSource.THRALL && !hit.isBlock())
			{
				total += hit.getAmount();
			}
		}
		return total;
	}

	public static String formatDamage(long damage)
	{
		return String.format("%,d", damage);
	}

	public static String formatAverage(Double average)
	{
		if (average == null)
		{
			return "\u2014";
		}
		return String.format("%.1f", average);
	}

	/**
	 * The number shown on a fight row. A max hit is marked beside the number.
	 */
	public static int countSplashes(Iterable<HitRecord> hits, @Nullable DamageDirection direction)
	{
		int count = 0;
		for (HitRecord hit : hits)
		{
			if (hit.isSplash() && (direction == null || hit.getDirection() == direction))
			{
				count++;
			}
		}
		return count;
	}

	public static String rowAmount(AttackRow row)
	{
		if (row.isSplash())
		{
			return "0";
		}
		if (isPunish(row))
		{
			StringBuilder parts = new StringBuilder();
			int shown = 0;
			for (HitRecord hit : row.getHits())
			{
				if (hit.getAmount() <= 0)
				{
					continue;
				}
				if (shown > 0)
				{
					parts.append('+');
				}
				parts.append(hit.getAmount());
				shown++;
			}
			if (shown >= 2)
			{
				return "(Punish) (" + parts + ") " + row.getTotal();
			}
			return "(Punish) " + row.getTotal();
		}
		String hits = specHits(row);
		if (hits != null)
		{
			String text = hits + " " + row.getTotal();
			if (maxHit(row))
			{
				text += " (Max hit)";
			}
			return text;
		}
		if (row.isBlock())
		{
			return "0";
		}
		String text = Integer.toString(row.getTotal());
		if (maxHit(row))
		{
			text += " (Max hit)";
		}
		return text;
	}

	/**
	 * The separate damaging hits of one special, such as {@code (20+30)}. A miss
	 * is left out, and a single hitsplat has nothing to spell out.
	 */
	@Nullable
	public static String specHits(AttackRow row)
	{
		if (!row.isSpecial() || row.getHits().size() < 2)
		{
			return null;
		}
		StringBuilder parts = new StringBuilder("(");
		int shown = 0;
		for (HitRecord hit : row.getHits())
		{
			if (hit.isBlock() || hit.getAmount() <= 0)
			{
				continue;
			}
			if (shown > 0)
			{
				parts.append('+');
			}
			parts.append(hit.getAmount());
			shown++;
		}
		if (shown < 2)
		{
			return null;
		}
		parts.append(')');
		return parts.toString();
	}

	private static boolean isPunish(AttackRow row)
	{
		for (HitRecord hit : row.getHits())
		{
			if (hit.getSource() == DamageSource.PUNISH)
			{
				return true;
			}
		}
		return false;
	}

	private static boolean maxHit(AttackRow row)
	{
		for (HitRecord hit : row.getHits())
		{
			if (hit.getKind() == HitKind.MAX_HIT)
			{
				return true;
			}
		}
		return false;
	}

	public static String amountLabel(HitRecord hit)
	{
		if (hit.isSplash())
		{
			return "Splash";
		}
		if (hit.isBlock())
		{
			return "Block";
		}
		String text = Integer.toString(hit.getAmount());
		if (hit.getKind() == HitKind.MAX_HIT)
		{
			text += " (Max hit)";
		}
		if (hit.getSource() == DamageSource.PUNISH)
		{
			return "(Punish) " + text;
		}
		if (hit.getOverkill() > 0)
		{
			text += " (" + hit.getOverkill() + " overkill)";
		}
		String effect = effectName(hit);
		if (!effect.isEmpty())
		{
			text += " " + effect;
		}
		return text;
	}

	public static String rowKind(AttackRow row)
	{
		HitRecord hit = row.first();
		if (row.isSplash())
		{
			return "Splash";
		}
		String status = statusLabel(hit.getSource());
		if (status != null)
		{
			return status;
		}
		if (hit.getSource() == DamageSource.PUNISH)
		{
			return hit.getDirection() == DamageDirection.INCOMING ? "Taken" : "Dealt";
		}
		if (row.isSpecial())
		{
			return "Spec";
		}
		return hit.getDirection() == DamageDirection.INCOMING ? "Taken" : "Dealt";
	}

	@Nullable
	public static String statusLabel(DamageSource source)
	{
		if (source == null)
		{
			return null;
		}
		switch (source)
		{
			case BURN:
				return "Burn";
			case POISON:
				return "Poison";
			case VENOM:
				return "Venom";
			default:
				return null;
		}
	}

	public static String effectName(HitRecord hit)
	{
		switch (hit.getSource())
		{
			case THRALL:
				return "thrall";
			case VENGEANCE:
				return "venge";
			case BURN:
				return "burn";
			case POISON:
				return "poison";
			case VENOM:
				return "venom";
			case BLEED:
				return "bleed";
			case DISEASE:
				return "disease";
			case CORRUPTION:
				return "corruption";
			case DOOM:
				return "doom";
			case PUNISH:
				return "";
			case PRAYER:
				return "prayer";
			case SANITY:
				return "sanity";
			default:
				return hit.getTint() == null ? "" : hit.getTint().toLowerCase(Locale.US);
		}
	}

	public static String attackLabel(AttackRow row)
	{
		if (row.isSpecial())
		{
			String text = rowAmount(row);
			if (row.getOverkill() > 0)
			{
				text += " (" + row.getOverkill() + " overkill)";
			}
			return text;
		}
		if (row.getHits().size() == 1)
		{
			return amountLabel(row.first());
		}
		StringBuilder parts = new StringBuilder();
		for (HitRecord hit : row.getHits())
		{
			if (hit.isBlock())
			{
				continue;
			}
			if (parts.length() > 0)
			{
				parts.append('+');
			}
			parts.append(hit.getAmount());
			if (hit.getKind() == HitKind.MAX_HIT)
			{
				parts.append(" (Max hit)");
			}
		}
		String text = row.getTotal() + " · " + parts;
		if (row.getOverkill() > 0)
		{
			text += " (" + row.getOverkill() + " overkill)";
		}
		String effect = effectName(row.first());
		if (!effect.isEmpty())
		{
			text += " " + effect;
		}
		return text;
	}

	public static String toClipboardText(CombatSnapshot snapshot, ZoneId zone)
	{
		StringBuilder text = new StringBuilder();
		text.append(CombatLogPlugin.NAME).append('\n');
		text.append("Total damage: ").append(formatDamage(snapshot.getTotalDamage())).append('\n');
		text.append("Hits: ").append(snapshot.getDamageHits()).append('\n');
		text.append("Blocks: ").append(snapshot.getBlocks()).append('\n');
		text.append("Max hit: ");
		text.append(snapshot.getDamageHits() == 0 ? "\u2014" : Integer.toString(snapshot.getMaxHit()));
		text.append('\n');
		text.append("Average hit: ").append(formatAverage(snapshot.getAverageHit())).append("\n\n");

		if (!snapshot.getTargets().isEmpty())
		{
			text.append("Targets\n");
			for (TargetTotal target : snapshot.getTargets())
			{
				text.append(target.getName());
				if (target.getKind() == TargetKind.PLAYER)
				{
					text.append(" (player)");
				}
				text.append('\t').append(target.getDamage());
				text.append(" damage\t").append(target.getHits()).append(target.getHits() == 1 ? " hit" : " hits");
				if (target.getBlocks() > 0)
				{
					text.append('\t').append(target.getBlocks()).append(target.getBlocks() == 1 ? " block" : " blocks");
				}
				text.append('\n');
			}
			text.append('\n');
		}

		text.append("Time\tTarget\tKind\tAmount\tResult\tTint\n");
		List<HitRecord> chronological = new ArrayList<>(snapshot.getHits());
		Collections.reverse(chronological);
		for (HitRecord hit : chronological)
		{
			text.append(formatTime(hit.getTimeMillis(), zone)).append('\t');
			text.append(hit.getTargetName()).append('\t');
			text.append(hit.getTargetKind() == TargetKind.PLAYER ? "Player" : "NPC").append('\t');
			text.append(hit.isMiss() ? 0 : hit.getAmount()).append('\t');
			text.append(resultLabel(hit)).append('\t');
			text.append(hit.getTint() == null ? "" : hit.getTint()).append('\n');
		}
		return text.toString();
	}

	private static String resultLabel(HitRecord hit)
	{
		if (hit.getKind() == HitKind.MAX_HIT)
		{
			return "Max hit";
		}
		if (hit.getKind() == HitKind.SPLASH)
		{
			return "Splash";
		}
		if (hit.getKind() == HitKind.BLOCK)
		{
			return "Block";
		}
		if (hit.getSource() == DamageSource.PUNISH)
		{
			return "Punish";
		}
		return "Hit";
	}
}

package com.combatlog;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import java.util.List;
import javax.inject.Inject;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.ComponentOrientation;
import net.runelite.client.ui.overlay.components.ImageComponent;
import net.runelite.client.ui.overlay.components.LayoutableRenderableEntity;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.SplitComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

class CombatLogOverlay extends OverlayPanel
{
	static final Color BLOCK_COLOR = new Color(150, 150, 150);
	static final Color PLAYER_COLOR = new Color(255, 176, 140);
	static final Color GROUP_LINE = new Color(55, 200, 90);
	private final CombatLog combatLog;
	private final CombatLogConfig config;
	private final MonsterIcons monsterIcons;
	private final WeaponIcons weaponIcons;
	private final StyleIcons styleIcons;
	private final PrayerIcons prayerIcons;
	private final GameHitsplats gameHitsplats;
	private CombatSnapshot snapshot;
	private int snapshotVersion;
	private DamageView snapshotView;

	@Inject
	CombatLogOverlay(CombatLogPlugin plugin, CombatLog combatLog, CombatLogConfig config, MonsterIcons monsterIcons, WeaponIcons weaponIcons, StyleIcons styleIcons, PrayerIcons prayerIcons, GameHitsplats gameHitsplats)
	{
		super(plugin);
		this.combatLog = combatLog;
		this.config = config;
		this.monsterIcons = monsterIcons;
		this.weaponIcons = weaponIcons;
		this.styleIcons = styleIcons;
		this.prayerIcons = prayerIcons;
		this.gameHitsplats = gameHitsplats;
		setPosition(OverlayPosition.TOP_LEFT);
		setPriority(PRIORITY_LOW);
		setResizable(false);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showOverlay())
		{
			return null;
		}

		CombatSnapshot snapshot = snapshot();
		if (snapshot.isEmpty())
		{
			return null;
		}

		Font font = FontManager.getRunescapeFont();
		if (font != null)
		{
			graphics.setFont(font);
		}

		panelComponent.getChildren().add(TitleComponent.builder()
			.text(CombatLogPlugin.NAME)
			.build());
		if (snapshot.getView() != DamageView.INCOMING)
		{
			panelComponent.getChildren().add(amountLine("Damage done", snapshot.getTotalDamage(), DamageColors.OUTGOING));
			int thrall = CombatLogFormatter.thrallDamage(snapshot.getHits());
			if (thrall > 0)
			{
				panelComponent.getChildren().add(amountLine("Thrall damage", thrall, Color.WHITE));
			}
		}
		if (snapshot.getView() != DamageView.OUTGOING)
		{
			panelComponent.getChildren().add(amountLine("Taken", snapshot.getDamageTaken(), DamageColors.INCOMING));
		}

		int shown = 0;
		int limit = Math.max(1, config.overlayHits());
		boolean drewGroup = false;
		for (Fight fight : snapshot.getFights())
		{
			if (shown >= limit)
			{
				break;
			}
			if (drewGroup)
			{
				panelComponent.getChildren().add(new GroupSeparator());
			}
			String footer = FightSummary.footer(fight, snapshot.getNowTick(), snapshot.getView(), true);
			if (footer != null)
			{
				panelComponent.getChildren().add(LineComponent.builder()
					.left(footer)
					.leftColor(BLOCK_COLOR)
					.build());
			}
			panelComponent.getChildren().add(fightTitle(fight, snapshot.getView()));
			String delve = DoomDelve.detail(fight.getDelve());
			if (delve != null)
			{
				panelComponent.getChildren().add(LineComponent.builder()
					.left(delve)
					.leftColor(BLOCK_COLOR)
					.build());
			}
			for (AttackRow attack : AttackRow.group(fight.visibleHits(snapshot.getView())))
			{
				if (shown >= limit)
				{
					break;
				}
				shown++;
				panelComponent.getChildren().add(hitRow(attack));
			}
			drewGroup = true;
		}

		panelComponent.setPreferredSize(new Dimension(overlayWidth(), 0));
		return super.render(graphics);
	}

	/**
	 * The overlay never reads time based fields, so a summary stays valid until
	 * the log changes or the view does.
	 */
	private CombatSnapshot snapshot()
	{
		DamageView view = damageView();
		int version = combatLog.version();
		if (snapshot == null || version != snapshotVersion || view != snapshotView)
		{
			snapshot = combatLog.summarize(System.currentTimeMillis(), 10, view);
			snapshotVersion = version;
			snapshotView = view;
		}
		return snapshot;
	}

	private int overlayWidth()
	{
		try
		{
			int width = config.overlayWidth();
			if (width < 120)
			{
				return 140;
			}
			return Math.min(width, 400);
		}
		catch (RuntimeException ex)
		{
			return 140;
		}
	}

	private DamageView damageView()
	{
		try
		{
			DamageView view = config.damageView();
			return view == null ? DamageView.OUTGOING : view;
		}
		catch (RuntimeException ex)
		{
			return DamageView.OUTGOING;
		}
	}

	private static LineComponent amountLine(String label, long amount, Color color)
	{
		return LineComponent.builder()
			.left(label)
			.right(CombatLogFormatter.formatDamage(amount))
			.rightColor(color)
			.build();
	}

	private LayoutableRenderableEntity fightTitle(Fight fight, DamageView view)
	{
		boolean taken = fight.showsTaken(view);
		LineComponent line = LineComponent.builder()
			.left(fight.getName())
			.leftColor(fight.getKind() == TargetKind.PLAYER ? PLAYER_COLOR : Color.WHITE)
			.right(CombatLogFormatter.formatDamage(fight.headerAmount(view)))
			.rightColor(taken ? DamageColors.INCOMING : DamageColors.OUTGOING)
			.build();
		BufferedImage monster = fight.getKind() == TargetKind.PLAYER
			? PlayerIcon.image(fight, monsterIcons, weaponIcons)
			: fight.getNpcId() == null || monsterIcons == null ? null : monsterIcons.get(fight.getNpcId());
		if (monster == null && fight.getNpcId() == null && monsterIcons != null && CombatDummy.named(fight.getName()))
		{
			monster = monsterIcons.get(CombatDummy.ICON_ID);
		}
		if (monster == null)
		{
			return line;
		}
		return SplitComponent.builder()
			.first(new ImageComponent(monster))
			.second(line)
			.orientation(ComponentOrientation.HORIZONTAL)
			.gap(new Point(4, 0))
			.build();
	}

	private LayoutableRenderableEntity hitRow(AttackRow attack)
	{
		HitRecord hit = attack.first();
		boolean incoming = hit.getDirection() == DamageDirection.INCOMING;
		boolean punish = hit.getSource() == DamageSource.PUNISH;
		boolean special = attack.isSpecial() && !punish;
		boolean splash = attack.isSplash();
		boolean status = hit.getSource().isStatus();
		String kind = CombatLogFormatter.rowKind(attack);
		Color kindColor = splash ? DamageColors.SPLASH : special && !status ? DamageColors.SPEC : incoming ? DamageColors.INCOMING : DamageColors.OUTGOING;
		boolean spelledOut = CombatLogFormatter.specHits(attack) != null || punish;
		BufferedImage splat = !spelledOut && config.damageAmount() == DamageAmount.HITSPLAT && gameHitsplats != null
			? gameHitsplats.image(attack)
			: null;
		String amount = splat == null ? CombatLogFormatter.rowAmount(attack) : maxNote(attack);
		Color amountColor = special && !status ? DamageColors.SPEC : DamageColors.forHit(hit);
		return new IconLine(kind, kindColor, amount, amountColor, hitIcon(hit), splat);
	}

	private BufferedImage hitIcon(HitRecord hit)
	{
		if (hit.getSource().isStatus() || hit.getSource() == DamageSource.PUNISH)
		{
			return null;
		}
		if (hit.getSource() == DamageSource.THRALL)
		{
			return Thralls.image(hit);
		}
		if (hit.getDirection() == DamageDirection.INCOMING && hit.getWeaponItemId() != null)
		{
			return weaponIcons.get(hit.getWeaponItemId());
		}
		if (hit.getDirection() == DamageDirection.INCOMING && hit.getCombatStyle() != null)
		{
			return styleIcons.get(hit.getCombatStyle());
		}
		return beside(weaponIcon(hit), prayerIcon(hit));
	}

	private static String maxNote(AttackRow attack)
	{
		for (HitRecord hit : attack.getHits())
		{
			if (hit.getKind() == HitKind.MAX_HIT)
			{
				return "(Max hit)";
			}
		}
		return "";
	}

	private BufferedImage prayerIcon(HitRecord hit)
	{
		if (hit.getDirection() != DamageDirection.OUTGOING || prayerIcons == null)
		{
			return null;
		}
		if (hit.getSource() != DamageSource.WEAPON)
		{
			return null;
		}
		return prayerIcons.get(hit.getPrayerIcon());
	}

	private static BufferedImage beside(BufferedImage weapon, BufferedImage prayer)
	{
		if (weapon == null)
		{
			return prayer;
		}
		if (prayer == null)
		{
			return weapon;
		}
		return Hitsplats.beside(weapon, prayer);
	}

	private BufferedImage weaponIcon(HitRecord hit)
	{
		Integer itemId = hit.getWeaponItemId();
		if (itemId != null)
		{
			return weaponIcons.get(itemId);
		}
		Integer style = hit.getAttackStyleIcon();
		if (style == null || prayerIcons == null)
		{
			return null;
		}
		return prayerIcons.get(style);
	}

	/**
	 * One hit, drawn inside the overlay width. The icon sits just left of the
	 * number so neither one is painted past the panel edge.
	 */
	private static final class IconLine implements LayoutableRenderableEntity
	{
		private static final int ICON_GAP = 3;

		private final String left;
		private final Color leftColor;
		private final String right;
		private final Color rightColor;
		private final BufferedImage icon;
		private final BufferedImage splat;
		private Point preferredLocation = new Point();
		private Dimension preferredSize = new Dimension();
		private final Rectangle bounds = new Rectangle();

		private IconLine(String left, Color leftColor, String right, Color rightColor, BufferedImage icon, BufferedImage splat)
		{
			this.left = left;
			this.leftColor = leftColor;
			this.right = right == null ? "" : right;
			this.rightColor = rightColor;
			this.icon = icon;
			this.splat = splat;
		}

		@Override
		public Dimension render(Graphics2D graphics)
		{
			FontMetrics metrics = graphics.getFontMetrics();
			int textHeight = metrics.getHeight();
			int iconWidth = icon == null ? 0 : icon.getWidth();
			int iconHeight = icon == null ? 0 : icon.getHeight();
			int splatWidth = splat == null ? 0 : splat.getWidth();
			int splatHeight = splat == null ? 0 : splat.getHeight();
			int leftWidth = metrics.stringWidth(left);
			int rightWidth = this.right.isEmpty() ? 0 : metrics.stringWidth(this.right);
			int iconGap = icon == null ? 0 : ICON_GAP;
			int splatGap = splat != null && rightWidth > 0 ? ICON_GAP : 0;
			int rowHeight = Math.max(textHeight, Math.max(iconHeight, splatHeight));
			int width = preferredSize.width > 0
				? preferredSize.width
				: leftWidth + 6 + iconWidth + iconGap + splatWidth + splatGap + rightWidth;

			int x = preferredLocation.x;
			int baseline = preferredLocation.y + (rowHeight - textHeight) / 2 + metrics.getAscent();
			graphics.setColor(leftColor);
			graphics.drawString(left, x, baseline);
			int block = splatWidth + splatGap + rightWidth;
			int blockX = x + width - block;
			if (splat != null)
			{
				int splatY = preferredLocation.y + Math.max(0, (rowHeight - splatHeight) / 2);
				graphics.drawImage(splat, blockX, splatY, null);
			}
			if (rightWidth > 0)
			{
				graphics.setColor(rightColor);
				graphics.drawString(this.right, blockX + splatWidth + splatGap, baseline);
			}
			if (icon != null)
			{
				int iconX = Math.max(x + leftWidth + 4, blockX - iconGap - iconWidth);
				int iconY = preferredLocation.y + Math.max(0, (rowHeight - iconHeight) / 2);
				graphics.drawImage(icon, iconX, iconY, null);
			}

			Dimension size = new Dimension(width, rowHeight);
			bounds.setLocation(preferredLocation);
			bounds.setSize(size);
			return size;
		}

		@Override
		public void setPreferredLocation(Point location)
		{
			preferredLocation = location;
		}

		@Override
		public void setPreferredSize(Dimension size)
		{
			preferredSize = size;
		}

		@Override
		public Rectangle getBounds()
		{
			return bounds;
		}
	}

	private static final class GroupSeparator implements LayoutableRenderableEntity
	{
		private static final int LINE = 2;
		private static final int PAD = 3;

		private Point preferredLocation = new Point();
		private Dimension preferredSize = new Dimension();
		private final Rectangle bounds = new Rectangle();

		@Override
		public Dimension render(Graphics2D graphics)
		{
			int width = Math.max(1, preferredSize.width);
			int y = preferredLocation.y + PAD;
			graphics.setColor(GROUP_LINE);
			graphics.fillRect(preferredLocation.x, y, width, LINE);
			Dimension size = new Dimension(width, LINE + PAD * 2);
			bounds.setLocation(preferredLocation);
			bounds.setSize(size);
			return size;
		}

		@Override
		public void setPreferredLocation(Point location)
		{
			preferredLocation = location;
		}

		@Override
		public void setPreferredSize(Dimension size)
		{
			preferredSize = size;
		}

		@Override
		public Rectangle getBounds()
		{
			return bounds;
		}
	}
}

