package com.combatlog;

import java.util.Locale;
import javax.annotation.Nullable;
import net.runelite.api.gameval.NpcID;

/**
 * The Doom of Mokhaiotl uses one NPC id at every depth. The delve number is the
 * current-level player variable, snapshotted onto the fight. Every form is the
 * same monster.
 */
final class DoomDelve
{
	static final String DISPLAY_NAME = "Doom of Mokhaiotl";

	private DoomDelve()
	{
	}

	/** Normal, shielded, and burrowed forms share one log name. */
	static String displayName(@Nullable String name, @Nullable Integer npcId)
	{
		if (isDoom(npcId) || named(name))
		{
			return DISPLAY_NAME;
		}
		return name;
	}

	static boolean named(@Nullable String name)
	{
		if (name == null)
		{
			return false;
		}
		String plain = Names.plain(name);
		if (plain == null)
		{
			return false;
		}
		plain = plain.toLowerCase(Locale.ROOT);
		return plain.equals("doom of mokhaiotl") || plain.startsWith("doom of mokhaiotl ");
	}

	static boolean isDoom(@Nullable Integer npcId)
	{
		return surface(npcId) || burrowed(npcId);
	}

	/**
	 * The form that is up and fighting: unshielded or behind the demonic
	 * shield. Both belong to one log for the delve.
	 */
	static boolean surface(@Nullable Integer npcId)
	{
		return npcId != null && (npcId == NpcID.DOM_BOSS || npcId == NpcID.DOM_BOSS_SHIELDED);
	}

	/** The underground car phase. From delve 5 it belongs to that delve's log. */
	static boolean burrowed(@Nullable Integer npcId)
	{
		return npcId != null && npcId == NpcID.DOM_BOSS_BURROWED;
	}

	/** Burrowed Doom first appears on delve 5, and shares that delve's fight. */
	static boolean burrowJoins(int level)
	{
		return level >= 5;
	}

	/**
	 * During a fight the player variable holds how many delves are already
	 * finished. 0 is the first fight, 1 is the second, and so on.
	 */
	static int level(int completedBefore)
	{
		if (completedBefore < 0)
		{
			return 0;
		}
		return completedBefore + 1;
	}

	@Nullable
	static String label(@Nullable Integer level)
	{
		if (level == null || level <= 0)
		{
			return null;
		}
		return "Delve " + level;
	}

	/**
	 * Hitpoints for that delve. Delve 7 stays at 650, delve 8 is 675, and
	 * delve 9 and deeper drop back to 625.
	 */
	static int maxHp(int level)
	{
		switch (level)
		{
			case 1:
				return 525;
			case 2:
				return 550;
			case 3:
				return 575;
			case 4:
				return 600;
			case 5:
				return 625;
			case 6:
			case 7:
				return 650;
			case 8:
				return 675;
			default:
				return level > 8 ? 625 : 0;
		}
	}

	@Nullable
	static String detail(@Nullable Integer level)
	{
		String delve = label(level);
		if (delve == null)
		{
			return null;
		}
		int hp = maxHp(level);
		if (hp <= 0)
		{
			return delve;
		}
		return delve + " \u00b7 HP: " + CombatLogFormatter.formatDamage(hp);
	}
}

package com.combatlog;

import net.runelite.api.gameval.AnimationID;

/**
 * Doom's yellow melee charge is interrupted by a melee hit. That hit adds
 * bonus damage of floor(visible strength bonus / 5), repeated once for each
 * hitsplat of a multi-hit weapon. Prayers and Void do not change it.
 */
final class DoomPunish
{
	/** A charge animation keeps the window open this many ticks. */
	static final int CHARGE_TICKS = 20;

	/** The bonus hitsplat can land a few ticks after the interrupt. */
	static final int LAND_TICKS = 4;

	private DoomPunish()
	{
	}

	static boolean charging(int animation)
	{
		return animation == AnimationID.DOM_BEAM_CHARGE || animation == AnimationID.DOM_BEAM_CHARGE_LOOP;
	}

	static boolean cancelled(int animation)
	{
		return animation == AnimationID.DOM_BEAM_CANCEL;
	}

	static boolean fired(int animation)
	{
		return animation == AnimationID.DOM_BEAM_FIRE;
	}

	/**
	 * Bonus damage for one hitsplat. {@code strengthBonus} is the gear strength
	 * bonus, the number shown on the equipment screen.
	 */
	static int bonus(int strengthBonus)
	{
		if (strengthBonus <= 0)
		{
			return 0;
		}
		return strengthBonus / 5;
	}
}

package com.combatlog;

import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import javax.annotation.Nullable;

public final class Fight
{
	private final long id;
	private final String name;
	private final TargetKind kind;
	@Nullable
	private final Integer npcIndex;
	@Nullable
	private Integer npcId;
	private final List<HitRecord> hits = new ArrayList<>();
	private final List<AttackSwing> attacks = new ArrayList<>();
	private int startTick;
	private int endTick;
	private boolean closed;
	private boolean killed;
	/** A finished attempt. Later hits at this delve start a new log. */
	private boolean sealed;
	private Integer maxHp;
	/** Head item id for a player. 0 means nothing is worn there. Null for an NPC. */
	@Nullable
	private Integer headItemId;
	/** Name of {@link #headItemId}, read on the client thread when the head was seen. */
	@Nullable
	private String headItemName;
	private Integer delve;
	/** Attack tick just before a phase left this fight, so that gap is not lost ticks. */
	private final List<Integer> phaseBreaks = new ArrayList<>();

	Fight(long id, String name, TargetKind kind, @Nullable Integer npcId, @Nullable Integer npcIndex, int tick)
	{
		this.id = id;
		String plain = Names.plain(name);
		this.name = DoomDelve.displayName(plain, npcId);
		this.kind = kind;
		this.npcId = npcId;
		this.npcIndex = npcIndex;
		this.startTick = tick;
		this.endTick = tick;
	}

	public long getId()
	{
		return id;
	}

	public String getName()
	{
		return name;
	}

	public TargetKind getKind()
	{
		return kind;
	}

	@Nullable
	public Integer getNpcId()
	{
		return npcId;
	}

	void setNpcId(int npcId)
	{
		this.npcId = npcId;
	}

	@Nullable
	public Integer getNpcIndex()
	{
		return npcIndex;
	}

	public List<HitRecord> getHits()
	{
		return Collections.unmodifiableList(hits);
	}

	public List<AttackSwing> getAttacks()
	{
		return Collections.unmodifiableList(attacks);
	}

	@Nullable
	public Integer getHeadItemId()
	{
		return headItemId;
	}

	@Nullable
	public String getHeadItemName()
	{
		return headItemName;
	}

	void setHead(int headItemId, @Nullable String headItemName)
	{
		this.headItemId = headItemId;
		this.headItemName = headItemId > 0 ? headItemName : null;
	}

	public int getStartTick()
	{
		return startTick;
	}

	public int getEndTick()
	{
		return endTick;
	}

	public boolean isClosed()
	{
		return closed;
	}

	public boolean isKilled()
	{
		return killed;
	}

	boolean isSealed()
	{
		return sealed;
	}

	/** This attempt is over. A later visit to the same delve is a new log. */
	void seal()
	{
		sealed = true;
	}

	public boolean hasTickTiming()
	{
		return startTick > 0 || endTick > 0;
	}

	@Nullable
	public Integer getMaxHp()
	{
		return maxHp;
	}

	void setMaxHp(int maxHp)
	{
		if (delve != null || maxHp <= 0)
		{
			return;
		}
		this.maxHp = maxHp;
	}

	@Nullable
	public Integer getDelve()
	{
		return delve;
	}

	/**
	 * The first positive reading wins. A later descent updates the player
	 * variable, and that value belongs to the next fight.
	 */
	void setDelve(int level)
	{
		if (delve != null || level <= 0)
		{
			return;
		}
		delve = level;
		int hp = DoomDelve.maxHp(level);
		if (hp > 0)
		{
			maxHp = hp;
		}
	}

	/**
	 * The boss left and came back, for example after burrowing. The idle gap
	 * is part of the delve, and it is not time the player failed to attack.
	 */
	void notePhaseResume(int tick)
	{
		int last = 0;
		for (AttackSwing swing : attacks)
		{
			if (swing.getTick() > last)
			{
				last = swing.getTick();
			}
		}
		if (last <= 0 || tick - last <= 8 || phaseBreaks.contains(last))
		{
			return;
		}
		phaseBreaks.add(last);
	}

	List<Integer> phaseBreaks()
	{
		return Collections.unmodifiableList(phaseBreaks);
	}

	int lastTick()
	{
		int last = startTick;
		for (HitRecord hit : hits)
		{
			if (hit.getTick() > last)
			{
				last = hit.getTick();
			}
		}
		return last;
	}

	void addHit(HitRecord hit)
	{
		hits.add(hit);
		if (!killed)
		{
			if (hits.size() == 1 || (hit.getTick() > 0 && startTick == 0))
			{
				startTick = hit.getTick();
			}
			if (hit.getTick() > endTick)
			{
				endTick = hit.getTick();
			}
		}
		if (npcId == null && hit.getNpcId() != null)
		{
			npcId = hit.getNpcId();
		}
	}

	Fight copy()
	{
		Fight copy = new Fight(id, name, kind, npcId, npcIndex, startTick);
		copy.hits.addAll(hits);
		copy.attacks.addAll(attacks);
		copy.endTick = endTick;
		copy.closed = closed;
		copy.killed = killed;
		copy.sealed = sealed;
		copy.maxHp = maxHp;
		copy.headItemId = headItemId;
		copy.headItemName = headItemName;
		copy.delve = delve;
		copy.phaseBreaks.addAll(phaseBreaks);
		return copy;
	}

	void removeHit(HitRecord hit)
	{
		hits.remove(hit);
	}

	void addAttack(AttackSwing swing)
	{
		attacks.add(swing);
		attacks.sort(Comparator.comparingInt(AttackSwing::getTick));
	}

	void markSpec(int tick, @Nullable Integer npcIndex)
	{
		for (int i = 0; i < attacks.size(); i++)
		{
			AttackSwing swing = attacks.get(i);
			if (swing.getTick() == tick && (npcIndex == null ? swing.getNpcIndex() == null : npcIndex.equals(swing.getNpcIndex())))
			{
				attacks.set(i, swing.withSpec());
			}
		}
	}

	void replaceWeapon(int tick, @Nullable Integer npcIndex, int weaponItemId, int speed)
	{
		for (int i = 0; i < attacks.size(); i++)
		{
			AttackSwing swing = attacks.get(i);
			if (swing.getTick() != tick)
			{
				continue;
			}
			if (npcIndex != null && swing.getNpcIndex() != null && !npcIndex.equals(swing.getNpcIndex()))
			{
				continue;
			}
			attacks.set(i, swing.withWeapon(weaponItemId, speed));
		}
	}

	void reopen()
	{
		closed = false;
		killed = false;
	}

	/** Pulls another form of this same delve onto this fight. */
	void takeFrom(Fight other)
	{
		reopen();
		if (other.startTick > 0 && (startTick == 0 || other.startTick < startTick))
		{
			startTick = other.startTick;
		}
		for (HitRecord hit : other.hits)
		{
			addHit(hit.withMeta(hit.getTick(), id, hit.getAttackId(), hit.getWeaponItemId(), hit.isSpecial(), hit.getSource(), hit.getOverkill(), hit.getSequence()));
		}
		for (AttackSwing swing : other.attacks)
		{
			addAttack(swing);
		}
		for (Integer tick : other.phaseBreaks)
		{
			if (!phaseBreaks.contains(tick))
			{
				phaseBreaks.add(tick);
			}
		}
	}

	void closeKilled(int tick)
	{
		closed = true;
		killed = true;
		if (tick > endTick)
		{
			endTick = tick;
		}
	}

	void closeQuiet(int tick)
	{
		closed = true;
		killed = false;
		sealed = true;
		endTick = tick;
	}

	public int damageDone()
	{
		return weaponDamage() + thrallDamage() + extraDamage();
	}

	/**
	 * Incoming shows damage taken. Both does too when nothing was dealt, so a
	 * fight that only received hits is not listed as zero.
	 */
	public boolean showsTaken(DamageView view)
	{
		if (view == DamageView.INCOMING)
		{
			return true;
		}
		return view == DamageView.BOTH && damageDone() == 0 && damageTaken() > 0;
	}

	public int headerAmount(DamageView view)
	{
		return showsTaken(view) ? damageTaken() : damageDone();
	}

	public int weaponDamage()
	{
		int damage = 0;
		for (HitRecord hit : hits)
		{
			if (hit.countsTowardWeaponDamage())
			{
				damage += hit.getAmount();
			}
		}
		return damage;
	}

	public int overkill()
	{
		int overkill = 0;
		for (HitRecord hit : hits)
		{
			if (hit.countsTowardWeaponDamage())
			{
				overkill += hit.getOverkill();
			}
		}
		return overkill;
	}

	public int extraDamage()
	{
		int damage = 0;
		for (HitRecord hit : hits)
		{
			if (hit.getDirection() == DamageDirection.OUTGOING && !hit.isBlock() && hit.getSource() != DamageSource.WEAPON && hit.getSource() != DamageSource.THRALL)
			{
				damage += hit.getAmount();
			}
		}
		return damage;
	}

	public int thrallDamage()
	{
		int damage = 0;
		for (HitRecord hit : hits)
		{
			if (hit.getDirection() == DamageDirection.OUTGOING && hit.getSource() == DamageSource.THRALL && !hit.isBlock())
			{
				damage += hit.getAmount();
			}
		}
		return damage;
	}

	public int damageTaken()
	{
		int damage = 0;
		for (HitRecord hit : hits)
		{
			if (hit.getDirection() == DamageDirection.INCOMING && !hit.isBlock())
			{
				damage += hit.getAmount();
			}
		}
		return damage;
	}

	public boolean visibleIn(DamageView view)
	{
		for (HitRecord hit : hits)
		{
			if (hit.visibleIn(view))
			{
				return true;
			}
		}
		return false;
	}

	public List<HitRecord> visibleHits(DamageView view)
	{
		List<HitRecord> visible = new ArrayList<>();
		for (HitRecord hit : hits)
		{
			if (hit.visibleIn(view))
			{
				visible.add(hit);
			}
		}
		visible.sort(Comparator.comparingLong(HitRecord::getTimeMillis).reversed());
		return visible;
	}
}

package com.combatlog;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;

/**
 * Groups hits by the individual being fought. An NPC is the actor instance
 * (its index), so two monsters that share a name stay in separate fights.
 * A player is keyed by name and is never merged with an NPC.
 */
public final class FightGroups
{
	private FightGroups()
	{
	}

	public static List<List<HitRecord>> group(List<HitRecord> hits)
	{
		Map<FightKey, List<HitRecord>> byTarget = new LinkedHashMap<>();
		for (HitRecord hit : hits)
		{
			FightKey key = FightKey.of(hit);
			List<HitRecord> group = byTarget.get(key);
			if (group == null)
			{
				group = new ArrayList<>();
				byTarget.put(key, group);
			}
			group.add(hit);
		}

		List<List<HitRecord>> groups = new ArrayList<>(byTarget.size());
		for (List<HitRecord> group : byTarget.values())
		{
			group.sort(Comparator.comparingLong(HitRecord::getTimeMillis).reversed());
			groups.add(group);
		}
		groups.sort(Comparator.comparingLong((List<HitRecord> group) -> group.get(0).getTimeMillis()).reversed());
		return groups;
	}

	private static final class FightKey
	{
		private final TargetKind kind;
		private final String name;
		private final Integer npcIndex;
		private final Long fightId;

		private FightKey(TargetKind kind, String name, Integer npcIndex, Long fightId)
		{
			this.kind = kind;
			this.name = name;
			this.npcIndex = npcIndex;
			this.fightId = fightId;
		}

		private static FightKey of(HitRecord hit)
		{
			if (hit.getFightId() != null)
			{
				return new FightKey(hit.getTargetKind(), hit.getTargetName(), null, hit.getFightId());
			}
			if (hit.getTargetKind() == TargetKind.PLAYER)
			{
				return new FightKey(TargetKind.PLAYER, hit.getTargetName(), null, null);
			}
			return new FightKey(TargetKind.NPC, hit.getTargetName(), hit.getNpcIndex(), null);
		}

		@Override
		public boolean equals(Object other)
		{
			if (this == other)
			{
				return true;
			}
			if (!(other instanceof FightKey))
			{
				return false;
			}
			FightKey key = (FightKey) other;
			return kind == key.kind && name.equals(key.name) && Objects.equals(npcIndex, key.npcIndex) && Objects.equals(fightId, key.fightId);
		}

		@Override
		public int hashCode()
		{
			return Objects.hash(kind, name, npcIndex, fightId);
		}
	}
}

package com.combatlog;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import javax.annotation.Nullable;

public final class FightSummary
{
	/**
	 * Fallback split for a fight that is not tied to one NPC. An NPC life
	 * stays one log until that NPC dies or despawns.
	 */
	static final int QUIET_TICKS = 16;
	static final int LATE_TICKS = 4;
	static final double TICK_SECONDS = 0.6;

	private FightSummary()
	{
	}

	public static int lostTicks(List<AttackSwing> attacks)
	{
		return lostTicks(attacks, Collections.emptyList());
	}

	static int lostTicks(Fight fight)
	{
		return lostTicks(fight.getAttacks(), fight.phaseBreaks());
	}

	private static int lostTicks(List<AttackSwing> attacks, List<Integer> phaseBreaks)
	{
		if (attacks.size() < 2)
		{
			return 0;
		}
		List<AttackSwing> ordered = new ArrayList<>(attacks);
		ordered.sort((left, right) -> Integer.compare(left.getTick(), right.getTick()));
		int lost = 0;
		for (int i = 1; i < ordered.size(); i++)
		{
			int previous = ordered.get(i - 1).getTick();
			int next = ordered.get(i).getTick();
			if (crossesPhaseBreak(phaseBreaks, previous, next))
			{
				continue;
			}
			int gap = next - previous;
			int speed = ordered.get(i - 1).getSpeed();
			if (gap > speed)
			{
				lost += gap - speed;
			}
		}
		return lost;
	}

	private static boolean crossesPhaseBreak(List<Integer> phaseBreaks, int previous, int next)
	{
		for (int breakTick : phaseBreaks)
		{
			if (breakTick >= previous && breakTick < next)
			{
				return true;
			}
		}
		return false;
	}

	@Nullable
	public static Integer accuracy(Fight fight)
	{
		int hits = 0;
		int blocks = 0;
		for (AttackRow row : AttackRow.group(fight.getHits()))
		{
			HitRecord first = row.first();
			if (first.getDirection() != DamageDirection.OUTGOING || first.getSource() != DamageSource.WEAPON)
			{
				continue;
			}
			if (row.isBlock() || row.isSplash())
			{
				blocks++;
			}
			else
			{
				hits++;
			}
		}
		if (hits + blocks == 0)
		{
			return null;
		}
		return (int) Math.round(100.0 * hits / (hits + blocks));
	}

	@Nullable
	public static String footer(Fight fight, int nowTick, DamageView view)
	{
		return footer(fight, nowTick, view, false);
	}

	/**
	 * @param overlay the game overlay uses Acc; the sidebar spells out Accuracy
	 */
	@Nullable
	public static String footer(Fight fight, int nowTick, DamageView view, boolean overlay)
	{
		if (!fight.hasTickTiming())
		{
			return null;
		}
		int end = fight.isClosed() ? fight.getEndTick() : Math.max(fight.getEndTick(), nowTick);
		int ticks = Math.max(0, end - fight.getStartTick());
		StringBuilder text = new StringBuilder();
		text.append(String.format(Locale.US, "%.1f", ticks * TICK_SECONDS)).append('s');
		if (!fight.isClosed())
		{
			text.append(" elapsed");
		}
		if (view == DamageView.INCOMING)
		{
			return text.toString();
		}
		if (ticks > 0)
		{
			Integer accuracy = accuracy(fight);
			if (accuracy != null)
			{
				text.append(" · ").append(overlay ? "Acc " : "Accuracy ").append(accuracy).append('%');
			}
		}
		int lost = lostTicks(fight);
		if (lost > 0)
		{
			text.append(" · Lost\u00a0ticks:\u00a0").append(lost);
		}
		return text.toString();
	}

	@Nullable
	public static String pace(List<Fight> fights, String name, TargetKind kind)
	{
		double best = Double.MAX_VALUE;
		int kills = 0;
		for (Fight fight : fights)
		{
			if (!fight.isKilled() || fight.getKind() != kind || !name.equals(fight.getName()))
			{
				continue;
			}
			double seconds = Math.max(0, fight.getEndTick() - fight.getStartTick()) * TICK_SECONDS;
			if (seconds < best)
			{
				best = seconds;
			}
			kills++;
		}
		if (kills == 0)
		{
			return null;
		}
		return String.format(Locale.US, "Best Time %.1fs · %d %s", best, kills, kills == 1 ? "kill" : "kills");
	}

	/**
	 * Kill count, average time, and best time for the finished fights of one monster.
	 */
	@Nullable
	public static String groupLine(List<Fight> fights)
	{
		if (fights.isEmpty())
		{
			return null;
		}
		int kills = 0;
		double total = 0;
		double best = Double.MAX_VALUE;
		for (Fight fight : fights)
		{
			if (!fight.isKilled() || !fight.hasTickTiming())
			{
				continue;
			}
			double seconds = Math.max(0, fight.getEndTick() - fight.getStartTick()) * TICK_SECONDS;
			total += seconds;
			kills++;
			if (seconds < best)
			{
				best = seconds;
			}
		}
		if (kills == 0)
		{
			int count = fights.size();
			return count + (count == 1 ? " fight" : " fights");
		}
		return String.format(Locale.US, "%d %s · avg %.1fs · best %.1fs",
			kills,
			kills == 1 ? "kill" : "kills",
			total / kills,
			best);
	}
}

package com.combatlog;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.Iterator;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.TreeSet;
import javax.annotation.Nullable;

/**
 * One open life per NPC index. Pausing damage does not start another log for
 * that same NPC. A death or despawn closes the life, and the next hit on that
 * index starts a new one. A quiet gap is only the fallback for fights that
 * are not tied to an NPC index.
 */
final class FightTracker
{
	private static final int WEAPON_WINDOW = 8;

	private final List<Fight> fights = new ArrayList<>();
	private final Map<String, Fight> open = new HashMap<>();
	private final Map<String, Fight> lastClosed = new HashMap<>();
	/** The open surface fight for each Doom delve. Shield and respawn share it. */
	private final Map<Integer, Fight> surfaceByLevel = new HashMap<>();
	private final Map<Long, Fight> byId = new HashMap<>();
	private final List<AttackSwing> queued = new ArrayList<>();
	private final TreeSet<Integer> activeTicks = new TreeSet<>();
	private final Map<String, HeadGear> playerHeads = new HashMap<>();
	private long nextFightId = 1;
	private long nextAttackId = 1;
	private int nextSequence;
	private int lastTick;
	/** Doom melee-charge window. Bonus hitsplats in it are the punish. */
	private int punishNpc = -1;
	private int punishStart = -1;
	private int punishUntil = -1;
	private int punishBonus;

	@Nullable
	HitRecord accept(HitRecord hit)
	{
		Fight fight = locate(hit);
		if (fight == null)
		{
			return null;
		}
		if (hit.getTick() > lastTick)
		{
			lastTick = hit.getTick();
		}
		Long attackId = hit.getAttackId();
		boolean special = hit.isSpecial();
		if (attackId == null && isPunish(fight, hit))
		{
			hit = hit.asSource(DamageSource.PUNISH, null, hit.getSourceNpcId());
			special = false;
		}
		if (attackId == null)
		{
			AttackSwing swing = selectSwing(fight, hit);
			if (swing != null)
			{
				attackId = swing.getAttackId();
				if (swing.isSpec() && hit.getSource() == DamageSource.WEAPON)
				{
					special = true;
				}
			}
			else
			{
				attackId = attackIdFor(fight, hit);
			}
		}
		HitRecord stored = hit.withMeta(hit.getTick(), fight.getId(), attackId, hit.getWeaponItemId(), special, hit.getSource(), hit.getOverkill(), nextSequence++);
		fight.addHit(stored);
		byId.put(fight.getId(), fight);
		return stored;
	}

	/**
	 * The NPC the player is already fighting, including the short window after
	 * it dies so the last incoming hit stays on that same log.
	 */
	/**
	 * The one player fight still open, so incoming damage can stay on it when
	 * the opponent is no longer the interaction target.
	 */
	@Nullable
	String soleOpenPlayer()
	{
		String name = null;
		for (Fight fight : open.values())
		{
			if (fight.isClosed() || fight.getKind() != TargetKind.PLAYER)
			{
				continue;
			}
			if (name != null)
			{
				return null;
			}
			name = fight.getName();
		}
		return name;
	}

	@Nullable
	Integer currentNpc(@Nullable Integer npcIndex, int tick)
	{
		if (npcIndex == null)
		{
			return null;
		}
		String key = npcKey(npcIndex);
		Fight current = open.get(key);
		if (current != null && !current.isClosed())
		{
			return npcIndex;
		}
		Fight closed = lastClosed.get(key);
		if (closed != null && closed.isKilled() && tick <= closed.getEndTick() + FightSummary.LATE_TICKS)
		{
			return npcIndex;
		}
		return null;
	}

	void closeLife(@Nullable Integer npcIndex, int tick)
	{
		if (npcIndex == null)
		{
			return;
		}
		if (tick > lastTick)
		{
			lastTick = tick;
		}
		String key = npcKey(npcIndex);
		Fight fight = open.get(key);
		if (fight == null || fight.isClosed())
		{
			return;
		}
		// From delve 5, one form despawning is a phase change. The delve log stays open.
		if (doomDelve(fight) && DoomDelve.burrowJoins(fight.getDelve()))
		{
			open.remove(key);
			return;
		}
		fight.closeKilled(tick);
		detach(fight, key);
	}

	/**
	 * Closes the life without a kill, for an NPC that left the scene while
	 * still alive. It does not count toward kills or best times.
	 */
	void closeQuiet(@Nullable Integer npcIndex, int tick)
	{
		if (npcIndex == null)
		{
			return;
		}
		if (tick > lastTick)
		{
			lastTick = tick;
		}
		String key = npcKey(npcIndex);
		Fight fight = open.get(key);
		if (fight == null || fight.isClosed())
		{
			return;
		}
		if (doomDelve(fight) && DoomDelve.burrowJoins(fight.getDelve()))
		{
			open.remove(key);
			return;
		}
		fight.closeQuiet(fight.lastTick());
		detach(fight, key);
	}

	/**
	 * Closes every open NPC life without a kill, for a logout or world hop
	 * where the NPCs leave the scene without despawn events.
	 */
	void closeAllQuiet(int tick)
	{
		if (tick > lastTick)
		{
			lastTick = tick;
		}
		for (Iterator<Map.Entry<String, Fight>> iterator = open.entrySet().iterator(); iterator.hasNext();)
		{
			Map.Entry<String, Fight> entry = iterator.next();
			Fight fight = entry.getValue();
			if (fight.getKind() != TargetKind.NPC)
			{
				continue;
			}
			if (!fight.isClosed())
			{
				fight.closeQuiet(fight.lastTick());
				lastClosed.put(entry.getKey(), fight);
				unmapSurface(fight);
			}
			iterator.remove();
		}
		surfaceByLevel.clear();
	}

	void noteForm(@Nullable Integer npcIndex, int npcId)
	{
		if (npcIndex == null)
		{
			return;
		}
		Fight fight = open.get(npcKey(npcIndex));
		if (fight == null)
		{
			return;
		}
		// The burrowed index is joined onto this fight. Keep the surface id so the
		// delve stays one log instead of becoming the burrowed NPC.
		if (DoomDelve.surface(fight.getNpcId()) && DoomDelve.burrowed(npcId))
		{
			return;
		}
		fight.setNpcId(npcId);
		if (DoomDelve.surface(npcId) && fight.getDelve() != null && !fight.isClosed())
		{
			surfaceByLevel.put(fight.getDelve(), fight);
		}
	}

	void noteMaxHp(@Nullable Integer npcIndex, int maxHp)
	{
		if (npcIndex == null || maxHp <= 0)
		{
			return;
		}
		Fight fight = open.get(npcKey(npcIndex));
		if (fight != null)
		{
			fight.setMaxHp(maxHp);
		}
	}

	void noteDelve(@Nullable Integer npcIndex, int level)
	{
		if (npcIndex == null || level <= 0)
		{
			return;
		}
		Fight fight = open.get(npcKey(npcIndex));
		if (fight == null || fight.isClosed())
		{
			return;
		}
		boolean first = fight.getDelve() == null;
		if (first && doomMonster(fight))
		{
			finishLowerSurfaces(level, fight);
			sealOtherDelves(level);
		}
		fight.setDelve(level);
		if (!doomMonster(fight) || fight.getDelve() == null || fight.getDelve() != level)
		{
			return;
		}
		foldDelve(level);
		if (!fights.contains(fight))
		{
			return;
		}
		Fight mapped = surfaceByLevel.get(level);
		if (mapped == null || mapped.isClosed() || mapped == fight)
		{
			surfaceByLevel.put(level, fight);
		}
	}

	/**
	 * A later spawn of the same delve, including the shield and the burrowed
	 * form, keeps using the fight already open for that level.
	 */
	void joinDoomSurface(@Nullable Integer npcIndex, int level)
	{
		if (npcIndex == null || level <= 0)
		{
			return;
		}
		Fight fight = delveFight(level);
		if (fight == null)
		{
			fight = openDoomForLevel(level);
		}
		if (fight == null)
		{
			return;
		}
		// A wipe is sealed and stays its own log. A phase that only looked
		// finished still belongs to this delve.
		if (fight.isClosed())
		{
			if (fight.isSealed() || !DoomDelve.burrowJoins(level))
			{
				return;
			}
			fight.reopen();
		}
		if (fight.getDelve() == null || fight.getDelve() == level)
		{
			surfaceByLevel.put(level, fight);
		}
		open.put(npcKey(npcIndex), fight);
		flushQueuedFor(fight, npcIndex);
	}

	/** The surface boss was gone and is back. The gap is not lost ticks. */
	void resumeDoomSurface(int tick)
	{
		for (Fight fight : surfaceByLevel.values())
		{
			if (!fight.isClosed())
			{
				fight.notePhaseResume(tick);
			}
		}
	}

	boolean hasOpenDoomSurface()
	{
		for (Fight fight : surfaceByLevel.values())
		{
			if (!fight.isClosed())
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Closes the surface fight once the delve is over. A kill is the boss
	 * dying. Leaving or wiping closes it without a kill.
	 */
	void finishDoomSurface(int tick, boolean killed)
	{
		if (tick > lastTick)
		{
			lastTick = tick;
		}
		List<Fight> finishing = new ArrayList<>();
		for (Fight fight : surfaceByLevel.values())
		{
			if (!fight.isClosed())
			{
				finishing.add(fight);
			}
		}
		for (Fight fight : finishing)
		{
			int end = fight.lastTick();
			if (killed)
			{
				fight.closeKilled(end);
			}
			else
			{
				fight.closeQuiet(end);
			}
			String key = fight.getNpcIndex() == null ? null : npcKey(fight.getNpcIndex());
			detach(fight, key);
		}
	}

	private void finishLowerSurfaces(int level, Fight current)
	{
		for (int lower = 1; lower < level; lower++)
		{
			if (DoomDelve.burrowJoins(lower))
			{
				foldDelve(lower);
			}
		}
		List<Fight> earlier = new ArrayList<>();
		for (Fight fight : new ArrayList<>(fights))
		{
			if (fight == current || fight.getDelve() == null || fight.getDelve() >= level || !doomMonster(fight))
			{
				continue;
			}
			if (!DoomDelve.burrowJoins(fight.getDelve()))
			{
				if (!fight.isClosed() && surfaceByLevel.get(fight.getDelve()) == fight)
				{
					earlier.add(fight);
				}
				continue;
			}
			if (!fight.isClosed())
			{
				earlier.add(fight);
			}
		}
		for (Fight previous : earlier)
		{
			previous.closeKilled(previous.lastTick());
			String key = previous.getNpcIndex() == null ? null : npcKey(previous.getNpcIndex());
			detach(previous, key);
		}
	}

	/**
	 * Starting a new run at delve 1 ends any deeper log still on the list.
	 * A deeper closed log is sealed so the next visit does not extend it.
	 */
	private void sealOtherDelves(int level)
	{
		if (level != 1)
		{
			return;
		}
		for (Fight fight : new ArrayList<>(fights))
		{
			if (fight.getDelve() == null || fight.getDelve() <= level || !doomMonster(fight) || fight.isSealed())
			{
				continue;
			}
			if (!fight.isClosed())
			{
				fight.closeQuiet(fight.lastTick());
				String key = fight.getNpcIndex() == null ? null : npcKey(fight.getNpcIndex());
				detach(fight, key);
			}
			else
			{
				fight.seal();
			}
		}
	}

	private void detach(Fight fight, @Nullable String primaryKey)
	{
		open.entrySet().removeIf(entry -> entry.getValue() == fight);
		if (primaryKey != null)
		{
			lastClosed.put(primaryKey, fight);
		}
		unmapSurface(fight);
	}

	private boolean doomMonster(Fight fight)
	{
		return DoomDelve.isDoom(fight.getNpcId()) || DoomDelve.DISPLAY_NAME.equals(fight.getName());
	}

	/** A delve log stays up while its forms come and go. */
	private boolean doomDelve(Fight fight)
	{
		return fight.getDelve() != null && doomMonster(fight);
	}

	@Nullable
	private Fight delveFight(int level)
	{
		Fight mapped = surfaceByLevel.get(level);
		if (mapped != null && !mapped.isClosed())
		{
			return mapped;
		}
		Fight closed = mapped;
		for (Fight fight : fights)
		{
			if (fight.getDelve() != null && fight.getDelve() == level && doomMonster(fight) && !fight.isClosed())
			{
				return fight;
			}
		}
		if (closed != null)
		{
			return closed;
		}
		for (Fight fight : fights)
		{
			if (fight.getDelve() != null && fight.getDelve() == level && doomMonster(fight))
			{
				return fight;
			}
		}
		return null;
	}

	/**
	 * One log for each delve from 5 up. Pieces of an attempt that is still
	 * open fold together no matter how long Doom was gone. A sealed wipe or
	 * a delve already left behind stays its own entry.
	 */
	boolean foldDoomLevels()
	{
		List<Integer> levels = new ArrayList<>();
		for (Fight fight : fights)
		{
			Integer delve = fight.getDelve();
			if (delve != null && DoomDelve.burrowJoins(delve) && !levels.contains(delve))
			{
				levels.add(delve);
			}
		}
		boolean changed = false;
		for (int level : levels)
		{
			changed |= foldDelve(level);
		}
		return changed;
	}

	private boolean foldDelve(int level)
	{
		if (!DoomDelve.burrowJoins(level))
		{
			return false;
		}
		List<Fight> same = new ArrayList<>();
		for (Fight candidate : new ArrayList<>(fights))
		{
			if (candidate.getDelve() != null && candidate.getDelve() == level && doomMonster(candidate) && !candidate.isSealed())
			{
				same.add(candidate);
			}
		}
		if (same.size() < 2)
		{
			return false;
		}
		boolean changed = false;
		Fight keeper = same.get(0);
		for (int i = 1; i < same.size(); i++)
		{
			Fight extra = same.get(i);
			changed = true;
			if (extra.getStartTick() - keeper.lastTick() > 8)
			{
				keeper.notePhaseResume(extra.getStartTick());
			}
			keeper.takeFrom(extra);
			for (Map.Entry<String, Fight> entry : new ArrayList<>(open.entrySet()))
			{
				if (entry.getValue() == extra)
				{
					open.put(entry.getKey(), keeper);
				}
			}
			dropFight(extra);
		}
		if (!keeper.isClosed())
		{
			surfaceByLevel.put(level, keeper);
		}
		return changed;
	}

	private void dropFight(Fight fight)
	{
		fights.remove(fight);
		byId.remove(fight.getId());
		open.entrySet().removeIf(entry -> entry.getValue() == fight);
		lastClosed.entrySet().removeIf(entry -> entry.getValue() == fight);
		unmapSurface(fight);
	}

	/**
	 * An open Doom fight for this delve. A fight whose delve is not set yet can
	 * still take the level, but a different delve cannot.
	 */
	@Nullable
	private Fight openDoomForLevel(int level)
	{
		Fight unset = null;
		for (Fight fight : open.values())
		{
			if (fight.isClosed() || !DoomDelve.isDoom(fight.getNpcId()))
			{
				continue;
			}
			if (fight.getDelve() != null && fight.getDelve() == level)
			{
				return fight;
			}
			if (fight.getDelve() == null)
			{
				unset = fight;
			}
		}
		return unset;
	}

	private void unmapSurface(Fight fight)
	{
		if (fight.getDelve() != null && surfaceByLevel.get(fight.getDelve()) == fight)
		{
			surfaceByLevel.remove(fight.getDelve());
			return;
		}
		surfaceByLevel.values().removeIf(mapped -> mapped == fight);
	}

	private void flushQueuedFor(Fight fight, int npcIndex)
	{
		Iterator<AttackSwing> iterator = queued.iterator();
		while (iterator.hasNext())
		{
			AttackSwing swing = iterator.next();
			if (!Objects.equals(swing.getNpcIndex(), npcIndex))
			{
				continue;
			}
			if (lastTick - swing.getTick() <= WEAPON_WINDOW)
			{
				fight.addAttack(swing);
			}
			iterator.remove();
		}
	}

	void noteAttack(AttackSwing swing)
	{
		if (swing.getAttackId() == 0)
		{
			swing = new AttackSwing(swing.getTick(), swing.getNpcIndex(), swing.getName(), swing.getWeaponItemId(), swing.getSpeed(), nextAttackId++);
		}
		if (duplicateSwing(swing))
		{
			return;
		}
		if (swing.getTick() > lastTick)
		{
			lastTick = swing.getTick();
		}
		int oldest = swing.getTick() - WEAPON_WINDOW;
		queued.removeIf(old -> old.getTick() < oldest);
		Fight fight = swing.getNpcIndex() != null ? open.get(npcKey(swing.getNpcIndex())) : open.get(playerKey(swing.getName()));
		if (fight != null && !fight.isClosed())
		{
			fight.addAttack(swing);
		}
		else
		{
			queued.add(swing);
		}
	}

	@Nullable
	Integer weaponFor(@Nullable Integer npcIndex, int tick, @Nullable Integer equipped)
	{
		AttackSwing swing = latestSwing(npcIndex, tick);
		if (swing != null && swing.getWeaponItemId() != null)
		{
			int gap = tick - swing.getTick();
			// A hit before the next attack can land still belongs to that swing,
			// even if the player has already equipped something else.
			if (equipped == null || equipped.equals(swing.getWeaponItemId()) || gap < swing.getSpeed())
			{
				return swing.getWeaponItemId();
			}
			return equipped;
		}
		return equipped;
	}

	/**
	 * The attack animation can be seen before the equipment packet. A weapon
	 * change on that same tick is the weapon that swung.
	 */
	void retargetWeapon(int tick, @Nullable Integer npcIndex, int weaponItemId, int speed)
	{
		for (Fight fight : fights)
		{
			fight.replaceWeapon(tick, npcIndex, weaponItemId, speed);
		}
		for (int i = 0; i < queued.size(); i++)
		{
			AttackSwing swing = queued.get(i);
			if (swing.getTick() != tick)
			{
				continue;
			}
			if (npcIndex != null && swing.getNpcIndex() != null && !npcIndex.equals(swing.getNpcIndex()))
			{
				continue;
			}
			queued.set(i, swing.withWeapon(weaponItemId, speed));
		}
	}

	boolean hasRecentAttack(@Nullable Integer npcIndex, int tick)
	{
		return latestSwing(npcIndex, tick) != null;
	}

	boolean fightingPlayer(@Nullable String name, int tick)
	{
		if (name == null || name.isEmpty())
		{
			return false;
		}
		Fight current = open.get(playerKey(name));
		if (current != null && !current.isClosed())
		{
			return true;
		}
		for (AttackSwing swing : queued)
		{
			if (swing.getNpcIndex() != null || !name.equals(swing.getName()))
			{
				continue;
			}
			int gap = tick - swing.getTick();
			if (gap >= 0 && gap <= WEAPON_WINDOW)
			{
				return true;
			}
		}
		return false;
	}

	void notePlayerHead(@Nullable String name, int itemId, @Nullable String itemName)
	{
		if (name == null || name.isEmpty() || itemId < 0)
		{
			return;
		}
		String shown = itemId > 0 ? itemName : null;
		playerHeads.put(name, new HeadGear(itemId, shown));
		Fight fight = open.get(playerKey(name));
		if (fight != null)
		{
			fight.setHead(itemId, shown);
		}
	}

	void noteCombatTick(int tick)
	{
		activeTicks.add(tick);
		if (tick > lastTick)
		{
			lastTick = tick;
		}
	}

	int getLastTick()
	{
		return lastTick;
	}

	int activeTickCount(int oldestTick)
	{
		return oldestTick <= 0 ? activeTicks.size() : activeTicks.tailSet(oldestTick).size();
	}

	void pruneTicksBefore(int tick)
	{
		activeTicks.headSet(tick).clear();
	}

	int queuedSize()
	{
		return queued.size();
	}

	List<Fight> fights()
	{
		List<Fight> copy = new ArrayList<>();
		for (Fight fight : fights)
		{
			if (!fight.getHits().isEmpty())
			{
				copy.add(fight.copy());
			}
		}
		copy.sort(Comparator.comparingLong((Fight fight) -> fight.lastTick()).reversed());
		return copy;
	}

	void remove(long fightId)
	{
		Fight fight = byId.remove(fightId);
		if (fight == null)
		{
			return;
		}
		fights.remove(fight);
		String key = key(fight);
		open.entrySet().removeIf(entry -> entry.getValue() == fight);
		if (lastClosed.get(key) == fight)
		{
			lastClosed.remove(key);
		}
		unmapSurface(fight);
	}

	void forget(HitRecord hit)
	{
		if (hit.getFightId() == null)
		{
			return;
		}
		Fight fight = byId.get(hit.getFightId());
		if (fight == null)
		{
			return;
		}
		fight.removeHit(hit);
		if (!fight.getHits().isEmpty())
		{
			return;
		}
		fights.remove(fight);
		byId.remove(fight.getId());
		String key = key(fight);
		open.entrySet().removeIf(entry -> entry.getValue() == fight);
		if (lastClosed.get(key) == fight)
		{
			lastClosed.remove(key);
		}
		unmapSurface(fight);
	}

	void clear()
	{
		fights.clear();
		open.clear();
		lastClosed.clear();
		surfaceByLevel.clear();
		byId.clear();
		queued.clear();
		activeTicks.clear();
		playerHeads.clear();
		lastTick = 0;
	}

	private Fight locate(HitRecord hit)
	{
		if (hit.getNpcIndex() == null && hit.getTargetKind() == TargetKind.NPC)
		{
			Fight only = soleOpenNpcFight();
			if (only != null)
			{
				return only;
			}
			// Incoming damage with no attacker used to open a fight named "Taken"
			// that never closed, because nothing can despawn. Leave it off the log.
			if (hit.getDirection() == DamageDirection.INCOMING)
			{
				return null;
			}
		}

		String key = key(hit);
		Fight current = open.get(key);
		if (current != null && !current.isClosed())
		{
			int last = current.lastTick();
			boolean sameNpc = hit.getNpcIndex() != null && hit.getTargetKind() == TargetKind.NPC;
			if (sameNpc || hit.getTick() <= 0 || hit.getTick() - last <= FightSummary.QUIET_TICKS)
			{
				return current;
			}
			current.closeQuiet(last);
			open.remove(key);
			lastClosed.put(key, current);
		}

		Fight closed = lastClosed.get(key);
		if (closed != null && closed.isKilled() && hit.getTick() <= closed.getEndTick() + FightSummary.LATE_TICKS)
		{
			return closed;
		}

		Fight created = new Fight(nextFightId++, hit.getTargetName(), hit.getTargetKind(), hit.getNpcId(), hit.getNpcIndex(), hit.getTick());
		if (hit.getTargetKind() == TargetKind.PLAYER)
		{
			HeadGear head = playerHeads.get(hit.getTargetName());
			if (head != null)
			{
				created.setHead(head.itemId, head.itemName);
			}
		}
		flushQueued(created, hit.getTick());
		fights.add(created);
		open.put(key, created);
		byId.put(created.getId(), created);
		return created;
	}

	private void flushQueued(Fight fight, int tick)
	{
		Iterator<AttackSwing> iterator = queued.iterator();
		while (iterator.hasNext())
		{
			AttackSwing swing = iterator.next();
			if (!sameTarget(fight, swing))
			{
				continue;
			}
			if (swing.getTick() <= tick && tick - swing.getTick() <= WEAPON_WINDOW)
			{
				fight.addAttack(swing);
				iterator.remove();
			}
			else if (tick - swing.getTick() > WEAPON_WINDOW)
			{
				iterator.remove();
			}
		}
	}

	/**
	 * Doom is charging a melee beam from {@code startTick} through {@code untilTick}.
	 * A hitsplat of {@code bonus} in that window is the punish, once the weapon
	 * swing already has a different hit. A charge that is already open keeps its start.
	 */
	void notePunish(int npcIndex, int startTick, int untilTick, int bonus)
	{
		if (untilTick < 0)
		{
			clearPunish();
			return;
		}
		int start = Math.max(0, startTick);
		if (punishUntil < start)
		{
			punishStart = start;
			punishNpc = npcIndex;
		}
		punishUntil = untilTick;
		punishBonus = Math.max(0, bonus);
	}

	void clearPunish()
	{
		punishNpc = -1;
		punishStart = -1;
		punishUntil = -1;
		punishBonus = 0;
	}

	void markSpecSwing(int tick, @Nullable Integer npcIndex)
	{
		for (Fight fight : fights)
		{
			fight.markSpec(tick, npcIndex);
		}
		for (int i = 0; i < queued.size(); i++)
		{
			AttackSwing swing = queued.get(i);
			if (swing.getTick() == tick && (npcIndex == null ? swing.getNpcIndex() == null : npcIndex.equals(swing.getNpcIndex())))
			{
				queued.set(i, swing.withSpec());
			}
		}
	}

	private boolean duplicateSwing(AttackSwing swing)
	{
		Fight fight = swing.getNpcIndex() != null ? open.get(npcKey(swing.getNpcIndex())) : open.get(playerKey(swing.getName()));
		if (fight != null)
		{
			for (AttackSwing existing : fight.getAttacks())
			{
				if (sameSwing(existing, swing))
				{
					return true;
				}
			}
		}
		for (AttackSwing existing : queued)
		{
			if (sameSwing(existing, swing))
			{
				return true;
			}
		}
		return false;
	}

	private static boolean sameSwing(AttackSwing existing, AttackSwing swing)
	{
		if (existing.getTick() != swing.getTick())
		{
			return false;
		}
		if (swing.getNpcIndex() != null || existing.getNpcIndex() != null)
		{
			return Objects.equals(existing.getNpcIndex(), swing.getNpcIndex());
		}
		return existing.getName().equals(swing.getName());
	}

	/**
	 * The newest swing this hit can belong to. A blowpipe dart is still in the
	 * air when the next shot starts, so a hitsplat on that tick stays with the
	 * earlier swing instead of the one that just began.
	 */
	@Nullable
	/**
	 * A hitsplat of the punish bonus while Doom is charging. It stays off the
	 * weapon swing so the special's own hits are left as they landed.
	 */
	private boolean isPunish(Fight fight, HitRecord hit)
	{
		if (punishBonus <= 0 || hit.getTick() < punishStart || hit.getTick() > punishUntil)
		{
			return false;
		}
		if (hit.getDirection() != DamageDirection.OUTGOING || hit.getSource() != DamageSource.WEAPON || hit.isBlock() || hit.isSplash())
		{
			return false;
		}
		if (hit.getAmount() != punishBonus)
		{
			return false;
		}
		boolean doom = DoomDelve.surface(hit.getNpcId()) || (hit.getNpcIndex() != null && hit.getNpcIndex() == punishNpc);
		if (!doom)
		{
			return false;
		}
		if (hasDifferentWeaponDamage(fight, hit))
		{
			return true;
		}
		AttackSwing swing = selectSwing(fight, hit);
		int slots = swing == null ? 0 : splatsFor(swing);
		return slots > 0 && bonusAlready(fight, swing) >= slots;
	}

	private boolean hasDifferentWeaponDamage(Fight fight, HitRecord hit)
	{
		for (HitRecord previous : fight.getHits())
		{
			if (previous.getDirection() != DamageDirection.OUTGOING || previous.isBlock() || previous.getAmount() <= 0)
			{
				continue;
			}
			if (previous.getTick() < punishStart || previous.getTick() > hit.getTick())
			{
				continue;
			}
			if (previous.getSource() != DamageSource.WEAPON && previous.getSource() != DamageSource.PUNISH)
			{
				continue;
			}
			if (previous.getAmount() != punishBonus)
			{
				return true;
			}
		}
		return false;
	}

	private int bonusAlready(Fight fight, AttackSwing swing)
	{
		int count = 0;
		for (HitRecord previous : fight.getHits())
		{
			if (previous.getAttackId() != null && previous.getAttackId() == swing.getAttackId() && previous.getAmount() == punishBonus && !previous.isBlock())
			{
				count++;
			}
		}
		return count;
	}

	private AttackSwing selectSwing(Fight fight, HitRecord hit)
	{
		if (hit.getDirection() != DamageDirection.OUTGOING || hit.getSource() == DamageSource.PUNISH)
		{
			return null;
		}
		// A missed tile of a special is not a new swing. It stays on that spec.
		// A block never belongs to a normal swing, so it stays its own row.
		if (hit.isBlock() || hit.getAmount() <= 0)
		{
			AttackSwing spec = openSpec(fight, hit);
			if (spec != null || hit.isBlock())
			{
				return spec;
			}
		}
		AttackSwing best = null;
		for (AttackSwing swing : fight.getAttacks())
		{
			if (!openSwing(fight, hit, swing))
			{
				continue;
			}
			if (swing.getTick() == hit.getTick() && earlierSwingWaiting(fight, hit, swing))
			{
				continue;
			}
			if (best == null || swing.getTick() >= best.getTick())
			{
				best = swing;
			}
		}
		return best;
	}

	private boolean earlierSwingWaiting(Fight fight, HitRecord hit, AttackSwing swing)
	{
		for (AttackSwing older : fight.getAttacks())
		{
			if (older.getTick() >= swing.getTick())
			{
				break;
			}
			if (openSwing(fight, hit, older))
			{
				return true;
			}
		}
		return false;
	}

	private boolean openSwing(Fight fight, HitRecord hit, AttackSwing swing)
	{
		int gap = hit.getTick() - swing.getTick();
		if (gap < 0 || gap > swing.getSpeed() + 2)
		{
			return false;
		}
		Integer swingWeapon = swing.getWeaponItemId();
		Integer hitWeapon = hit.getWeaponItemId();
		if (hitWeapon != null && swingWeapon != null && !hitWeapon.equals(swingWeapon))
		{
			return false;
		}
		return claimed(fight, swing.getAttackId()) < splatsFor(swing);
	}

	@Nullable
	private AttackSwing openSpec(Fight fight, HitRecord hit)
	{
		AttackSwing best = null;
		for (AttackSwing swing : fight.getAttacks())
		{
			if (!swing.isSpec())
			{
				continue;
			}
			int gap = hit.getTick() - swing.getTick();
			if (gap < 0 || gap > swing.getSpeed() + 2)
			{
				continue;
			}
			Integer swingWeapon = swing.getWeaponItemId();
			Integer hitWeapon = hit.getWeaponItemId();
			if (hitWeapon != null && swingWeapon != null && !hitWeapon.equals(swingWeapon))
			{
				continue;
			}
			if (best == null || swing.getTick() >= best.getTick())
			{
				best = swing;
			}
		}
		return best;
	}

	private Long attackIdFor(Fight fight, HitRecord hit)
	{
		if (hit.getDirection() == DamageDirection.OUTGOING && !hit.isBlock())
		{
			for (int i = fight.getHits().size() - 1; i >= 0; i--)
			{
				HitRecord previous = fight.getHits().get(i);
				if (previous.isBlock() || previous.getDirection() != DamageDirection.OUTGOING || previous.getSource() != hit.getSource())
				{
					continue;
				}
				if (previous.getTick() > 0 && previous.getTick() == hit.getTick() && Objects.equals(previous.getWeaponItemId(), hit.getWeaponItemId()) && previous.getAttackId() != null
					&& claimed(fight, previous.getAttackId()) < splatsFor(previous.getWeaponItemId()))
				{
					return previous.getAttackId();
				}
				break;
			}
		}
		return nextAttackId++;
	}

	private static int claimed(Fight fight, long attackId)
	{
		int count = 0;
		for (HitRecord previous : fight.getHits())
		{
			if (!previous.isBlock() && previous.getAmount() > 0 && previous.getAttackId() != null && previous.getAttackId() == attackId)
			{
				count++;
			}
		}
		return count;
	}

	private static int splatsFor(AttackSwing swing)
	{
		if (swing.isSpec())
		{
			int weaponId = swing.getWeaponItemId() == null ? 0 : swing.getWeaponItemId();
			return Math.max(1, SpecWeapons.splats(weaponId));
		}
		return normalSplats(swing.getWeaponItemId());
	}

	private static int splatsFor(@Nullable Integer weaponId)
	{
		return Math.max(normalSplats(weaponId), weaponId == null ? 1 : SpecWeapons.splats(weaponId));
	}

	private static int normalSplats(@Nullable Integer weaponId)
	{
		if (weaponId == null || weaponId <= 0)
		{
			return 1;
		}
		// A scythe swing on a large monster lands three hitsplats. A normal
		// blowpipe swing lands one, so later hits must not join that row.
		if (weaponId == 22325 || weaponId == 25736 || weaponId == 25739)
		{
			return 3;
		}
		if (weaponId == 28997)
		{
			return 2;
		}
		return 1;
	}

	@Nullable
	private AttackSwing latestSwing(@Nullable Integer npcIndex, int tick)
	{
		AttackSwing found = null;
		for (Fight fight : fights)
		{
			if (!Objects.equals(fight.getNpcIndex(), npcIndex))
			{
				continue;
			}
			for (AttackSwing swing : fight.getAttacks())
			{
				int gap = tick - swing.getTick();
				if (gap >= 0 && gap <= WEAPON_WINDOW && (found == null || swing.getTick() > found.getTick()))
				{
					found = swing;
				}
			}
		}
		for (AttackSwing swing : queued)
		{
			if (!Objects.equals(swing.getNpcIndex(), npcIndex))
			{
				continue;
			}
			int gap = tick - swing.getTick();
			if (gap >= 0 && gap <= WEAPON_WINDOW && (found == null || swing.getTick() > found.getTick()))
			{
				found = swing;
			}
		}
		return found;
	}

	@Nullable
	private Fight soleOpenNpcFight()
	{
		Fight found = null;
		for (Fight fight : open.values())
		{
			if (fight.isClosed() || fight.getKind() != TargetKind.NPC || fight.getNpcIndex() == null)
			{
				continue;
			}
			if (found != null)
			{
				return null;
			}
			found = fight;
		}
		return found;
	}

	private static boolean sameTarget(Fight fight, AttackSwing swing)
	{
		if (fight.getKind() == TargetKind.PLAYER)
		{
			return fight.getName().equals(swing.getName());
		}
		return Objects.equals(fight.getNpcIndex(), swing.getNpcIndex());
	}

	private static String key(HitRecord hit)
	{
		if (hit.getTargetKind() == TargetKind.PLAYER)
		{
			return playerKey(hit.getTargetName());
		}
		if (hit.getNpcIndex() != null)
		{
			return npcKey(hit.getNpcIndex());
		}
		return "npc-name:" + hit.getTargetName();
	}

	private static String key(Fight fight)
	{
		if (fight.getKind() == TargetKind.PLAYER)
		{
			return playerKey(fight.getName());
		}
		if (fight.getNpcIndex() != null)
		{
			return npcKey(fight.getNpcIndex());
		}
		return "npc-name:" + fight.getName();
	}

	private static String npcKey(int npcIndex)
	{
		return "npc:" + npcIndex;
	}

	private static String playerKey(String name)
	{
		return "player:" + name;
	}

	private static final class HeadGear
	{
		private final int itemId;
		@Nullable
		private final String itemName;

		private HeadGear(int itemId, @Nullable String itemName)
		{
			this.itemId = itemId;
			this.itemName = itemName;
		}
	}
}

package com.combatlog;

import java.awt.Color;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.SwingUtilities;
import net.runelite.api.gameval.SpriteID;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.ui.FontManager;

/**
 * Damage amounts drawn on the cache hitsplat. {@link SpriteManager} loads the
 * blank splat and {@link FontManager} stamps the number, which is how the
 * client paints a hitsplat. The hitsplat definition opcodes are not in the
 * public API, so each kind uses a {@link SpriteID.Hitmark} id.
 */
@Singleton
class GameHitsplats
{
	private final SpriteManager spriteManager;
	private final ConcurrentHashMap<Integer, BufferedImage> backgrounds = new ConcurrentHashMap<>();
	private final ConcurrentHashMap<String, BufferedImage> stamped = new ConcurrentHashMap<>();
	private final Set<Integer> pending = ConcurrentHashMap.newKeySet();
	private volatile Runnable onLoaded;

	@Inject
	GameHitsplats(SpriteManager spriteManager)
	{
		this.spriteManager = spriteManager;
	}

	void onLoaded(Runnable callback)
	{
		onLoaded = callback;
	}

	BufferedImage image(AttackRow row)
	{
		if (row == null || spriteManager == null)
		{
			return null;
		}
		int spriteId = spriteFor(row.first());
		String text = digits(row);
		String key = spriteId + ":" + text;
		BufferedImage ready = stamped.get(key);
		if (ready != null)
		{
			return ready;
		}
		BufferedImage background = backgrounds.get(spriteId);
		if (background == null)
		{
			request(spriteId);
			return null;
		}
		ready = stamp(background, text);
		stamped.put(key, ready);
		return ready;
	}

	static int spriteFor(HitRecord hit)
	{
		if (hit == null)
		{
			return SpriteID.Hitmark._1;
		}
		switch (hit.getSource())
		{
			case POISON:
				return SpriteID.Hitmark.HITSPLAT_GREEN_POISON;
			case VENOM:
				return SpriteID.Hitmark.HITSPLAT_DARK_GREEN_VENOM;
			case BURN:
				return SpriteID.Hitmark.BURN_DAMAGE;
			case DOOM:
				return SpriteID.Hitmark.COLOSSEUM_DOOM;
			case DISEASE:
				return SpriteID.Hitmark._3;
			default:
				break;
		}
		if (hit.isBlock() || hit.isSplash())
		{
			return SpriteID.Hitmark.HITSPLAT_BLUE_MISS;
		}
		if ("Cyan".equals(hit.getTint()))
		{
			return SpriteID.Hitmark._6;
		}
		return SpriteID.Hitmark._1;
	}

	static String digits(AttackRow row)
	{
		if (row.isBlock() || row.isSplash())
		{
			return "0";
		}
		return Integer.toString(Math.max(0, row.getTotal()));
	}

	static BufferedImage stamp(BufferedImage background, String text)
	{
		BufferedImage image = new BufferedImage(background.getWidth(), background.getHeight(), BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = image.createGraphics();
		graphics.drawImage(background, 0, 0, null);
		if (text != null && !text.isEmpty())
		{
			Font font = hitsplatFont();
			graphics.setFont(font);
			graphics.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);
			FontMetrics metrics = graphics.getFontMetrics();
			int x = Math.max(0, (image.getWidth() - metrics.stringWidth(text)) / 2);
			int y = (image.getHeight() - metrics.getHeight()) / 2 + metrics.getAscent();
			graphics.setColor(Color.BLACK);
			graphics.drawString(text, x + 1, y);
			graphics.drawString(text, x - 1, y);
			graphics.drawString(text, x, y + 1);
			graphics.drawString(text, x, y - 1);
			graphics.setColor(Color.WHITE);
			graphics.drawString(text, x, y);
		}
		graphics.dispose();
		return image;
	}

	private void request(int spriteId)
	{
		if (spriteId <= 0 || !pending.add(spriteId))
		{
			return;
		}
		spriteManager.getSpriteAsync(spriteId, 0, image -> finish(spriteId, image));
	}

	private void finish(int spriteId, BufferedImage image)
	{
		try
		{
			if (image == null)
			{
				return;
			}
			backgrounds.put(spriteId, image);
			Runnable callback = onLoaded;
			if (callback != null)
			{
				SwingUtilities.invokeLater(callback);
			}
		}
		finally
		{
			pending.remove(spriteId);
		}
	}

	private static Font hitsplatFont()
	{
		Font font = FontManager.getRunescapeSmallFont();
		if (font == null)
		{
			font = FontManager.getRunescapeFont();
		}
		if (font == null)
		{
			font = new Font(Font.DIALOG, Font.BOLD, 12);
		}
		return font;
	}
}

package com.combatlog;

import javax.annotation.Nullable;
import net.runelite.api.Player;
import net.runelite.api.PlayerComposition;
import net.runelite.api.kit.KitType;

/**
 * The item in another player's head slot. {@link PlayerComposition#getEquipmentId}
 * is the client API for worn gear and already returns the item id, or -1 when
 * that slot is a kit instead of an item.
 */
final class HeadSlot
{
	static final int BARE = 0;

	private HeadSlot()
	{
	}

	/**
	 * @return the head item id, {@link #BARE} when nothing is worn there, or
	 * null when the player model is not available
	 */
	@Nullable
	static Integer itemId(@Nullable Player player)
	{
		if (player == null)
		{
			return null;
		}
		PlayerComposition composition = player.getPlayerComposition();
		if (composition == null)
		{
			return null;
		}
		int id = composition.getEquipmentId(KitType.HEAD);
		if (id <= 0)
		{
			return BARE;
		}
		return id;
	}
}

package com.combatlog;

import javax.annotation.Nullable;

/**
 * Decides whether a hitsplat is one of your hits on an enemy, and turns it
 * into a log row. Kept separate from the plugin so the rules can be tested
 * without a running client.
 */
public final class HitCapture
{
	private HitCapture()
	{
	}

	@Nullable
	public static HitRecord capture(
		int hitsplatType,
		int amount,
		@Nullable String actorName,
		@Nullable TargetKind targetKind,
		@Nullable Integer npcId,
		@Nullable Integer npcIndex,
		@Nullable Integer weaponItemId,
		boolean self,
		boolean includeBlocks,
		boolean recordPlayers,
		long nowMillis)
	{
		if (self || targetKind == null)
		{
			return null;
		}

		HitStyle style = HitStyle.fromHitsplatType(hitsplatType);
		if (style == null)
		{
			return null;
		}
		if (style.getKind() == HitKind.BLOCK && !includeBlocks)
		{
			return null;
		}
		if (targetKind == TargetKind.PLAYER && !recordPlayers)
		{
			return null;
		}

		String name = actorName == null || actorName.isEmpty() ? "Unknown" : actorName;
		return new HitRecord(nowMillis, name, targetKind, npcId, npcIndex, weaponItemId, amount, style.getKind(), style.getTint());
	}

	@Nullable
	public static HitRecord captureIncoming(
		int hitsplatType,
		int amount,
		@Nullable String actorName,
		@Nullable TargetKind targetKind,
		@Nullable Integer npcId,
		@Nullable Integer npcIndex,
		long nowMillis,
		int tick,
		boolean includeBlocks)
	{
		HitStyle style = HitStyle.fromIncomingType(hitsplatType);
		if (style == null || targetKind == null)
		{
			return null;
		}
		if (style.getKind() == HitKind.BLOCK)
		{
			if (!includeBlocks)
			{
				return null;
			}
		}
		else if (amount <= 0)
		{
			return null;
		}
		String name = actorName == null || actorName.isEmpty() ? "Taken" : actorName;
		DamageSource source = HitStyle.incomingSource(hitsplatType);
		return new HitRecord(nowMillis, name, targetKind, npcId, npcIndex, null, amount, style.getKind(), style.getTint(), tick, DamageDirection.INCOMING, source, false, 0, null, null, 0);
	}

	@Nullable
	public static DamageSource statusSource(int hitsplatType)
	{
		if (hitsplatType == net.runelite.api.HitsplatID.BURN)
		{
			return DamageSource.BURN;
		}
		if (hitsplatType == net.runelite.api.HitsplatID.POISON)
		{
			return DamageSource.POISON;
		}
		if (hitsplatType == net.runelite.api.HitsplatID.VENOM)
		{
			return DamageSource.VENOM;
		}
		return null;
	}

	@Nullable
	public static HitRecord captureStatus(
		int hitsplatType,
		int amount,
		@Nullable String actorName,
		@Nullable TargetKind targetKind,
		@Nullable Integer npcId,
		@Nullable Integer npcIndex,
		long nowMillis,
		int tick)
	{
		DamageSource source = statusSource(hitsplatType);
		if (source == null || targetKind == null || amount <= 0)
		{
			return null;
		}
		String name = actorName == null || actorName.isEmpty() ? "Unknown" : actorName;
		return new HitRecord(nowMillis, name, targetKind, npcId, npcIndex, null, amount, HitKind.HIT, null, tick, DamageDirection.OUTGOING, source, false, 0, null, null, 0);
	}
}

package com.combatlog;

