package com.combatlog;

import javax.annotation.Nullable;

public final class HitRecord
{
	private final long timeMillis;
	private final String targetName;
	private final TargetKind targetKind;
	@Nullable
	private final Integer npcId;
	@Nullable
	private final Integer npcIndex;
	@Nullable
	private final Integer weaponItemId;
	private final int amount;
	private final HitKind kind;
	@Nullable
	private final String tint;
	private final int tick;
	private final DamageDirection direction;
	private final DamageSource source;
	private final boolean special;
	private final int overkill;
	@Nullable
	private final Long attackId;
	@Nullable
	private final Long fightId;
	private final int sequence;
	@Nullable
	private final Integer sourceNpcId;
	@Nullable
	private final CombatStyle combatStyle;
	@Nullable
	private final Integer prayerIcon;
	@Nullable
	private final Integer attackStyleIcon;

	public HitRecord(long timeMillis, String targetName, TargetKind targetKind, @Nullable Integer npcId, @Nullable Integer npcIndex, @Nullable Integer weaponItemId, int amount, HitKind kind, @Nullable String tint)
	{
		this(timeMillis, targetName, targetKind, npcId, npcIndex, weaponItemId, amount, kind, tint, 0, DamageDirection.OUTGOING, DamageSource.WEAPON, false, 0, null, null, 0);
	}

	public HitRecord(long timeMillis, String targetName, TargetKind targetKind, @Nullable Integer npcId, @Nullable Integer npcIndex, @Nullable Integer weaponItemId, int amount, HitKind kind, @Nullable String tint, int tick, DamageDirection direction, DamageSource source, boolean special, int overkill, @Nullable Long attackId, @Nullable Long fightId, int sequence)
	{
		this(timeMillis, targetName, targetKind, npcId, npcIndex, weaponItemId, amount, kind, tint, tick, direction, source, special, overkill, attackId, fightId, sequence, null);
	}

	public HitRecord(long timeMillis, String targetName, TargetKind targetKind, @Nullable Integer npcId, @Nullable Integer npcIndex, @Nullable Integer weaponItemId, int amount, HitKind kind, @Nullable String tint, int tick, DamageDirection direction, DamageSource source, boolean special, int overkill, @Nullable Long attackId, @Nullable Long fightId, int sequence, @Nullable Integer sourceNpcId)
	{
		this(timeMillis, targetName, targetKind, npcId, npcIndex, weaponItemId, amount, kind, tint, tick, direction, source, special, overkill, attackId, fightId, sequence, sourceNpcId, null);
	}

	public HitRecord(long timeMillis, String targetName, TargetKind targetKind, @Nullable Integer npcId, @Nullable Integer npcIndex, @Nullable Integer weaponItemId, int amount, HitKind kind, @Nullable String tint, int tick, DamageDirection direction, DamageSource source, boolean special, int overkill, @Nullable Long attackId, @Nullable Long fightId, int sequence, @Nullable Integer sourceNpcId, @Nullable CombatStyle combatStyle)
	{
		this(timeMillis, targetName, targetKind, npcId, npcIndex, weaponItemId, amount, kind, tint, tick, direction, source, special, overkill, attackId, fightId, sequence, sourceNpcId, combatStyle, null, null);
	}

	public HitRecord(long timeMillis, String targetName, TargetKind targetKind, @Nullable Integer npcId, @Nullable Integer npcIndex, @Nullable Integer weaponItemId, int amount, HitKind kind, @Nullable String tint, int tick, DamageDirection direction, DamageSource source, boolean special, int overkill, @Nullable Long attackId, @Nullable Long fightId, int sequence, @Nullable Integer sourceNpcId, @Nullable CombatStyle combatStyle, @Nullable Integer prayerIcon, @Nullable Integer attackStyleIcon)
	{
		this.timeMillis = timeMillis;
		this.targetName = Names.plain(targetName);
		this.targetKind = targetKind;
		this.npcId = targetKind == TargetKind.NPC ? npcId : null;
		this.npcIndex = targetKind == TargetKind.NPC ? npcIndex : null;
		this.weaponItemId = weaponItemId != null && weaponItemId > 0 ? weaponItemId : null;
		this.amount = amount;
		this.kind = kind;
		this.tint = tint;
		this.tick = tick;
		this.direction = direction == null ? DamageDirection.OUTGOING : direction;
		this.source = source == null ? DamageSource.WEAPON : source;
		this.special = special;
		this.overkill = Math.max(0, overkill);
		this.attackId = attackId;
		this.fightId = fightId;
		this.sequence = sequence;
		this.sourceNpcId = sourceNpcId != null && sourceNpcId > 0 ? sourceNpcId : null;
		this.combatStyle = combatStyle;
		this.prayerIcon = prayerIcon != null && prayerIcon > 0 ? prayerIcon : null;
		this.attackStyleIcon = attackStyleIcon != null && attackStyleIcon > 0 ? attackStyleIcon : null;
	}

	public HitRecord withMeta(int tick, @Nullable Long fightId, @Nullable Long attackId, @Nullable Integer weaponItemId, boolean special, DamageSource source, int overkill, int sequence)
	{
		Integer weapon = weaponItemId != null && weaponItemId > 0 ? weaponItemId : this.weaponItemId;
		return new HitRecord(timeMillis, targetName, targetKind, npcId, npcIndex, weapon, amount, kind, tint, tick, direction, source == null ? this.source : source, special, overkill, attackId, fightId, sequence, sourceNpcId, combatStyle, prayerIcon, attackStyleIcon);
	}

	public HitRecord withSourceNpc(@Nullable Integer sourceNpcId)
	{
		return new HitRecord(timeMillis, targetName, targetKind, npcId, npcIndex, weaponItemId, amount, kind, tint, tick, direction, source, special, overkill, attackId, fightId, sequence, sourceNpcId, combatStyle, prayerIcon, attackStyleIcon);
	}

	public HitRecord asSource(DamageSource source, @Nullable Integer weaponItemId, @Nullable Integer sourceNpcId)
	{
		return new HitRecord(timeMillis, targetName, targetKind, npcId, npcIndex, weaponItemId, amount, kind, tint, tick, direction, source == null ? this.source : source, special, overkill, attackId, fightId, sequence, sourceNpcId, combatStyle, prayerIcon, attackStyleIcon);
	}

	public HitRecord withWeapon(@Nullable Integer weaponItemId)
	{
		return new HitRecord(timeMillis, targetName, targetKind, npcId, npcIndex, weaponItemId, amount, kind, tint, tick, direction, source, special, overkill, attackId, fightId, sequence, sourceNpcId, combatStyle, prayerIcon, attackStyleIcon);
	}

	public HitRecord withStyle(@Nullable CombatStyle combatStyle)
	{
		return new HitRecord(timeMillis, targetName, targetKind, npcId, npcIndex, weaponItemId, amount, kind, tint, tick, direction, source, special, overkill, attackId, fightId, sequence, sourceNpcId, combatStyle, prayerIcon, attackStyleIcon);
	}

	public HitRecord withPrayer(@Nullable Integer prayerIcon)
	{
		return new HitRecord(timeMillis, targetName, targetKind, npcId, npcIndex, weaponItemId, amount, kind, tint, tick, direction, source, special, overkill, attackId, fightId, sequence, sourceNpcId, combatStyle, prayerIcon, attackStyleIcon);
	}

	public HitRecord withAttackStyle(@Nullable Integer attackStyleIcon)
	{
		return new HitRecord(timeMillis, targetName, targetKind, npcId, npcIndex, weaponItemId, amount, kind, tint, tick, direction, source, special, overkill, attackId, fightId, sequence, sourceNpcId, combatStyle, prayerIcon, attackStyleIcon);
	}

	public HitRecord asSplash()
	{
		return new HitRecord(timeMillis, targetName, targetKind, npcId, npcIndex, weaponItemId, amount, HitKind.SPLASH, tint, tick, direction, source, special, overkill, attackId, fightId, sequence, sourceNpcId, combatStyle, prayerIcon, attackStyleIcon);
	}

	public long getTimeMillis()
	{
		return timeMillis;
	}

	public String getTargetName()
	{
		return targetName;
	}

	public TargetKind getTargetKind()
	{
		return targetKind;
	}

	@Nullable
	public Integer getNpcId()
	{
		return npcId;
	}

	@Nullable
	public Integer getNpcIndex()
	{
		return npcIndex;
	}

	@Nullable
	public Integer getWeaponItemId()
	{
		return weaponItemId;
	}

	public int getAmount()
	{
		return amount;
	}

	public HitKind getKind()
	{
		return kind;
	}

	@Nullable
	public String getTint()
	{
		return tint;
	}

	public int getTick()
	{
		return tick;
	}

	public DamageDirection getDirection()
	{
		return direction;
	}

	public DamageSource getSource()
	{
		return source;
	}

	public boolean isSpecial()
	{
		return special;
	}

	public int getOverkill()
	{
		return overkill;
	}

	@Nullable
	public Long getAttackId()
	{
		return attackId;
	}

	@Nullable
	public Long getFightId()
	{
		return fightId;
	}

	public int getSequence()
	{
		return sequence;
	}

	@Nullable
	public Integer getSourceNpcId()
	{
		return sourceNpcId;
	}

	@Nullable
	public CombatStyle getCombatStyle()
	{
		return combatStyle;
	}

	@Nullable
	public Integer getPrayerIcon()
	{
		return prayerIcon;
	}

	@Nullable
	public Integer getAttackStyleIcon()
	{
		return attackStyleIcon;
	}

	public boolean isBlock()
	{
		return kind == HitKind.BLOCK;
	}

	public boolean isSplash()
	{
		return kind == HitKind.SPLASH;
	}

	public boolean isMiss()
	{
		return kind == HitKind.BLOCK || kind == HitKind.SPLASH;
	}

	public boolean countsTowardWeaponDamage()
	{
		return direction == DamageDirection.OUTGOING && source == DamageSource.WEAPON && !isMiss();
	}

	public boolean visibleIn(DamageView view)
	{
		if (view == DamageView.INCOMING)
		{
			return direction == DamageDirection.INCOMING;
		}
		if (view == DamageView.OUTGOING)
		{
			return direction == DamageDirection.OUTGOING;
		}
		return true;
	}

	public String describe()
	{
		StringBuilder description = new StringBuilder();
		if (kind == HitKind.MAX_HIT)
		{
			description.append("Max hit");
		}
		else if (kind == HitKind.SPLASH)
		{
			description.append("Splash");
		}
		else if (kind == HitKind.BLOCK)
		{
			description.append("Block");
		}
		else
		{
			description.append("Hit");
		}
		if (tint != null)
		{
			description.append(" (").append(tint).append(')');
		}
		description.append(" on ").append(targetName);
		if (targetKind == TargetKind.PLAYER)
		{
			description.append(" (player)");
		}
		if (!isMiss())
		{
			description.append(" for ").append(amount);
		}
		if (special)
		{
			description.append(" (spec)");
		}
		return description.toString();
	}
}

package com.combatlog;

import javax.annotation.Nullable;
import net.runelite.api.HitsplatID;

/**
 * How one of your hitsplats should be recorded.
 * <p>
 * The cases here match {@code Hitsplat.isMine()}. Poison, venom, burn, bleed,
 * and other players' splats are intentionally absent: the client does not
 * attribute them to you.
 */
public final class HitStyle
{
	private final HitKind kind;
	@Nullable
	private final String tint;

	private HitStyle(HitKind kind, @Nullable String tint)
	{
		this.kind = kind;
		this.tint = tint;
	}

	public HitKind getKind()
	{
		return kind;
	}

	@Nullable
	public String getTint()
	{
		return tint;
	}

	@Nullable
	public static HitStyle fromHitsplatType(int hitsplatType)
	{
		switch (hitsplatType)
		{
			case HitsplatID.DAMAGE_ME:
				return new HitStyle(HitKind.HIT, null);
			case HitsplatID.DAMAGE_ME_CYAN:
				return new HitStyle(HitKind.HIT, "Cyan");
			case HitsplatID.DAMAGE_ME_YELLOW:
				return new HitStyle(HitKind.HIT, "Yellow");
			case HitsplatID.DAMAGE_ME_ORANGE:
				return new HitStyle(HitKind.HIT, "Orange");
			case HitsplatID.DAMAGE_ME_WHITE:
				return new HitStyle(HitKind.HIT, "White");
			case HitsplatID.DAMAGE_ME_POISE:
				return new HitStyle(HitKind.HIT, "Poise");
			case HitsplatID.DAMAGE_MAX_ME:
				return new HitStyle(HitKind.MAX_HIT, null);
			case HitsplatID.DAMAGE_MAX_ME_CYAN:
				return new HitStyle(HitKind.MAX_HIT, "Cyan");
			case HitsplatID.DAMAGE_MAX_ME_ORANGE:
				return new HitStyle(HitKind.MAX_HIT, "Orange");
			case HitsplatID.DAMAGE_MAX_ME_YELLOW:
				return new HitStyle(HitKind.MAX_HIT, "Yellow");
			case HitsplatID.DAMAGE_MAX_ME_WHITE:
				return new HitStyle(HitKind.MAX_HIT, "White");
			case HitsplatID.DAMAGE_MAX_ME_POISE:
				return new HitStyle(HitKind.MAX_HIT, "Poise");
			case HitsplatID.BLOCK_ME:
				return new HitStyle(HitKind.BLOCK, null);
			default:
				return null;
		}
	}

	/**
	 * Damage the client did not attribute to you. Doom's punish bonus arrives
	 * this way: it is your hit, but it is not one of the "me" hitsplat ids.
	 */
	public static boolean othersDamage(int hitsplatType)
	{
		switch (hitsplatType)
		{
			case HitsplatID.DAMAGE_OTHER:
			case HitsplatID.DAMAGE_OTHER_CYAN:
			case HitsplatID.DAMAGE_OTHER_YELLOW:
			case HitsplatID.DAMAGE_OTHER_ORANGE:
			case HitsplatID.DAMAGE_OTHER_WHITE:
			case HitsplatID.DAMAGE_OTHER_POISE:
				return true;
			default:
				return false;
		}
	}

	@Nullable
	public static HitStyle fromIncomingType(int hitsplatType)
	{
		// Damage on the local player uses the same "me" ids as damage you deal.
		HitStyle onSelf = fromHitsplatType(hitsplatType);
		if (onSelf != null)
		{
			return onSelf;
		}
		switch (hitsplatType)
		{
			case HitsplatID.DAMAGE_OTHER:
				return new HitStyle(HitKind.HIT, null);
			case HitsplatID.DAMAGE_OTHER_CYAN:
				return new HitStyle(HitKind.HIT, "Cyan");
			case HitsplatID.DAMAGE_OTHER_YELLOW:
				return new HitStyle(HitKind.HIT, "Yellow");
			case HitsplatID.DAMAGE_OTHER_ORANGE:
				return new HitStyle(HitKind.HIT, "Orange");
			case HitsplatID.DAMAGE_OTHER_WHITE:
				return new HitStyle(HitKind.HIT, "White");
			case HitsplatID.DAMAGE_OTHER_POISE:
				return new HitStyle(HitKind.HIT, "Poise");
			case HitsplatID.BLOCK_OTHER:
				return new HitStyle(HitKind.BLOCK, null);
			case HitsplatID.POISON:
			case HitsplatID.VENOM:
			case HitsplatID.BLEED:
			case HitsplatID.BURN:
			case HitsplatID.DISEASE:
			case HitsplatID.CORRUPTION:
			case HitsplatID.DOOM:
			case HitsplatID.PRAYER_DRAIN:
			case HitsplatID.SANITY_DRAIN:
				return new HitStyle(HitKind.HIT, null);
			default:
				return null;
		}
	}

	public static DamageSource incomingSource(int hitsplatType)
	{
		switch (hitsplatType)
		{
			case HitsplatID.POISON:
				return DamageSource.POISON;
			case HitsplatID.VENOM:
				return DamageSource.VENOM;
			case HitsplatID.BLEED:
				return DamageSource.BLEED;
			case HitsplatID.BURN:
				return DamageSource.BURN;
			case HitsplatID.DISEASE:
				return DamageSource.DISEASE;
			case HitsplatID.CORRUPTION:
				return DamageSource.CORRUPTION;
			case HitsplatID.DOOM:
				return DamageSource.DOOM;
			case HitsplatID.PRAYER_DRAIN:
				return DamageSource.PRAYER;
			case HitsplatID.SANITY_DRAIN:
				return DamageSource.SANITY;
			default:
				return DamageSource.WEAPON;
		}
	}
}

package com.combatlog;

import java.awt.Color;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.HashMap;
import java.util.Map;
import net.runelite.client.ui.FontManager;

/**
 * Spiky hitsplat marks. Red is damage you deal, blue is damage you take.
 */
final class Hitsplats
{
	private static final String[] SPLAT = {
		"........s..........",
		"......s.#.s........",
		"....s..###..s.s....",
		"..s.s.#####.s..s...",
		".s..#########..s...",
		"..s###########s.s..",
		".s#############s.s.",
		"s###############s..",
		".#################.",
		"s#################s",
		".#################.",
		"s###############s..",
		".s#############s.s.",
		"..s###########s.s..",
		"...s.#########..s..",
		"....s.s#####s.s....",
		"......s.###.s......",
		".......s.s.s.......",
		".........s........."
	};

	private static final Color RED = new Color(214, 12, 12);
	private static final Color RED_DARK = new Color(148, 0, 0);
	private static final Color RED_TIP = new Color(92, 0, 0);
	private static final Color BLUE = new Color(24, 36, 214);
	private static final Color BLUE_DARK = new Color(8, 12, 150);
	private static final Color BLUE_TIP = new Color(0, 8, 96);

	private static final double SPRITE_SCALE = 1.5;

	private static final Map<String, BufferedImage> CACHE = new HashMap<>();

	private Hitsplats()
	{
	}

	static BufferedImage mark(boolean incoming)
	{
		String key = incoming ? "mark-in" : "mark-out";
		BufferedImage cached = CACHE.get(key);
		if (cached != null)
		{
			return cached;
		}
		BufferedImage image = paint(incoming, null, null);
		CACHE.put(key, image);
		return image;
	}

	static BufferedImage both()
	{
		BufferedImage cached = CACHE.get("mark-both");
		if (cached != null)
		{
			return cached;
		}
		BufferedImage image = beside(mark(false), mark(true));
		CACHE.put("mark-both", image);
		return image;
	}

	static BufferedImage amount(boolean incoming, String text)
	{
		String shown = text == null || text.isEmpty() ? "0" : text;
		String key = (incoming ? "in:" : "out:") + shown;
		BufferedImage cached = CACHE.get(key);
		if (cached != null)
		{
			return cached;
		}
		Font font = FontManager.getRunescapeFont();
		if (font == null)
		{
			font = FontManager.getRunescapeSmallFont();
		}
		if (font == null)
		{
			font = new Font(Font.DIALOG, Font.BOLD, 15);
		}
		else
		{
			font = font.deriveFont(Font.BOLD, 15f);
		}
		BufferedImage image = paint(incoming, shown, font);
		CACHE.put(key, image);
		return image;
	}

	static BufferedImage beside(BufferedImage left, BufferedImage right)
	{
		int gap = 3;
		int width = left.getWidth() + gap + right.getWidth();
		int height = Math.max(left.getHeight(), right.getHeight());
		BufferedImage image = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		g.drawImage(left, 0, (height - left.getHeight()) / 2, null);
		g.drawImage(right, left.getWidth() + gap, (height - right.getHeight()) / 2, null);
		g.dispose();
		return image;
	}

	static String[] parts(AttackRow row)
	{
		String label = CombatLogFormatter.attackLabel(row);
		if (row.isBlock() || row.isSplash())
		{
			return new String[] {"0", ""};
		}
		String number = CombatLogFormatter.rowAmount(row);
		String note;
		String split = row.getTotal() + " \u00b7 ";
		if (label.startsWith(split))
		{
			note = label.substring(split.length());
		}
		else if (label.startsWith(number))
		{
			note = label.substring(number.length()).trim();
		}
		else
		{
			note = label;
		}
		return new String[] {number, note};
	}

	private static BufferedImage paint(boolean incoming, String text, Font font)
	{
		int textWidth = 0;
		int textHeight = 0;
		if (text != null)
		{
			BufferedImage probe = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB);
			Graphics2D probeGraphics = probe.createGraphics();
			probeGraphics.setFont(font);
			FontMetrics metrics = probeGraphics.getFontMetrics();
			textWidth = metrics.stringWidth(text);
			textHeight = metrics.getHeight();
			probeGraphics.dispose();
		}
		char[][] grid = shape(textWidth + 6);
		int rows = grid.length;
		int cols = grid[0].length;
		BufferedImage image = new BufferedImage(cols, rows, BufferedImage.TYPE_INT_ARGB);
		Color core = incoming ? BLUE : RED;
		Color dark = incoming ? BLUE_DARK : RED_DARK;
		Color tip = incoming ? BLUE_TIP : RED_TIP;
		for (int y = 0; y < rows; y++)
		{
			for (int x = 0; x < cols; x++)
			{
				char cell = grid[y][x];
				if (cell == '.')
				{
					continue;
				}
				Color color = core;
				if (cell == 's')
				{
					color = neighbors(grid, x, y) <= 1 ? tip : dark;
				}
				image.setRGB(x, y, color.getRGB());
			}
		}
		if (text != null && textHeight + 4 > rows)
		{
			int targetHeight = textHeight + 4;
			int targetWidth = Math.max(cols, (int) Math.round(cols * (targetHeight / (double) rows)));
			BufferedImage scaled = new BufferedImage(targetWidth, targetHeight, BufferedImage.TYPE_INT_ARGB);
			Graphics2D scaledGraphics = scaled.createGraphics();
			scaledGraphics.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
			scaledGraphics.drawImage(image, 0, 0, targetWidth, targetHeight, null);
			scaledGraphics.dispose();
			image = scaled;
			cols = targetWidth;
			rows = targetHeight;
		}
		if (text != null)
		{
			Graphics2D g = image.createGraphics();
			g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_OFF);
			g.setFont(font);
			FontMetrics metrics = g.getFontMetrics();
			int x = (cols - metrics.stringWidth(text)) / 2;
			int y = (rows - metrics.getHeight()) / 2 + metrics.getAscent() - 1;
			g.setColor(Color.BLACK);
			for (int ox = -1; ox <= 1; ox++)
			{
				for (int oy = -1; oy <= 1; oy++)
				{
					if (ox != 0 || oy != 0)
					{
						g.drawString(text, x + ox, y + oy);
					}
				}
			}
			g.setColor(Color.WHITE);
			g.drawString(text, x, y);
			g.dispose();
		}
		return enlarge(image);
	}

	private static BufferedImage enlarge(BufferedImage image)
	{
		int width = Math.max(1, (int) Math.round(image.getWidth() * SPRITE_SCALE));
		int height = Math.max(1, (int) Math.round(image.getHeight() * SPRITE_SCALE));
		if (width == image.getWidth() && height == image.getHeight())
		{
			return image;
		}
		BufferedImage scaled = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = scaled.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
		g.drawImage(image, 0, 0, width, height, null);
		g.dispose();
		return scaled;
	}

	private static char[][] shape(int minCore)
	{
		int rows = SPLAT.length;
		int cols = SPLAT[0].length();
		int mid = cols / 2;
		int core = 0;
		for (int x = 0; x < cols; x++)
		{
			if (SPLAT[rows / 2].charAt(x) == '#')
			{
				core++;
			}
		}
		int extra = Math.max(0, minCore - core);
		char[][] grid = new char[rows][cols + extra];
		for (int y = 0; y < rows; y++)
		{
			int dx = 0;
			for (int x = 0; x < cols; x++)
			{
				grid[y][dx++] = SPLAT[y].charAt(x);
				if (x == mid)
				{
					for (int i = 0; i < extra; i++)
					{
						grid[y][dx++] = SPLAT[y].charAt(mid);
					}
				}
			}
		}
		return grid;
	}

	private static int neighbors(char[][] grid, int x, int y)
	{
		int count = 0;
		for (int oy = -1; oy <= 1; oy++)
		{
			for (int ox = -1; ox <= 1; ox++)
			{
				if (ox == 0 && oy == 0)
				{
					continue;
				}
				int nx = x + ox;
				int ny = y + oy;
				if (ny >= 0 && ny < grid.length && nx >= 0 && nx < grid[ny].length && grid[ny][nx] != '.')
				{
					count++;
				}
			}
		}
		return count;
	}
}

package com.combatlog;

import javax.annotation.Nullable;

/**
 * Who an incoming hit belongs to when no NPC is actually fighting the player.
 * A pet must never be passed in here: callers drop followers before asking.
 */
final class IncomingPlayer
{
	private IncomingPlayer()
	{
	}

	@Nullable
	static String name(@Nullable String interacting, @Nullable String soleAggro, @Nullable String openFight)
	{
		if (present(interacting))
		{
			return interacting;
		}
		if (present(soleAggro))
		{
			return soleAggro;
		}
		if (present(openFight))
		{
			return openFight;
		}
		return null;
	}

	private static boolean present(@Nullable String name)
	{
		return name != null && !name.isEmpty();
	}
}

package com.combatlog;

import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;
import java.util.Objects;
import javax.annotation.Nullable;
import net.runelite.api.Actor;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.SpotanimID;

/**
 * Remembers projectiles aimed at the player so an incoming hit can be marked
 * melee, ranged, or magic. A hit with no projectile is melee. A projectile is
 * ranged unless it is a known magic spell or comes from a magic-only monster.
 * An attack graphic is not enough: ranged attacks use spotanims too.
 */
final class IncomingStyles
{
	private static final int MATCH_BEFORE = 80;
	private static final int MATCH_AFTER = 40;
	private static final int KEEP = 200;

	private final List<Seen> recent = new ArrayList<>();
	private final List<Seen> playerSpells = new ArrayList<>();

	void clear()
	{
		recent.clear();
		playerSpells.clear();
	}

	void noteProjectile(@Nullable Integer npcIndex, int endCycle, boolean magic)
	{
		noteProjectile(npcIndex, endCycle, 0, magic);
	}

	void noteProjectile(@Nullable Integer npcIndex, int endCycle, int projectileId, boolean magic)
	{
		for (Seen seen : recent)
		{
			if (Objects.equals(seen.npcIndex, npcIndex) && seen.endCycle == endCycle)
			{
				seen.magic = seen.magic || magic;
				if (projectileId > 0)
				{
					seen.projectileId = projectileId;
				}
				return;
			}
		}
		recent.add(new Seen(npcIndex, endCycle, projectileId, magic));
	}

	void notePlayerSpell(@Nullable Integer npcIndex, int endCycle)
	{
		for (Seen seen : playerSpells)
		{
			if (Objects.equals(seen.npcIndex, npcIndex) && seen.endCycle == endCycle)
			{
				return;
			}
		}
		playerSpells.add(new Seen(npcIndex, endCycle, 0, true));
	}

	/**
	 * True when a spell the player cast is landing on this NPC now.
	 * A spell with no target matches whichever NPC the zero lands on.
	 */
	boolean playerSpellLanding(@Nullable Integer npcIndex, int cycle)
	{
		prune(cycle);
		for (Seen seen : playerSpells)
		{
			int gap = seen.endCycle - cycle;
			if (gap > MATCH_AFTER || gap < -MATCH_BEFORE)
			{
				continue;
			}
			if (npcIndex == null)
			{
				if (seen.npcIndex == null)
				{
					return true;
				}
				continue;
			}
			if (seen.npcIndex == null || seen.npcIndex.equals(npcIndex))
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * A shot that starts on the player's tile and ends somewhere else is the
	 * player's own attack. Standing next to the target puts that end tile
	 * inside the incoming range, which would mark a melee hit as ranged.
	 */
	static boolean leavesPlayer(@Nullable WorldPoint source, @Nullable WorldPoint target, @Nullable WorldPoint playerTile)
	{
		if (!sameTile(source, playerTile) || target == null)
		{
			return false;
		}
		return !sameTile(target, playerTile);
	}

	private static boolean sameTile(@Nullable WorldPoint left, @Nullable WorldPoint right)
	{
		return left != null && right != null && left.getPlane() == right.getPlane() && left.getX() == right.getX() && left.getY() == right.getY();
	}

	/**
	 * A projectile is aimed at the player when it targets them, or when its
	 * destination is on their tile. NPC bolts often have no target actor.
	 */
	static boolean aimedAt(
		@Nullable Actor targetActor,
		@Nullable Actor interacting,
		@Nullable Actor player,
		@Nullable WorldPoint target,
		@Nullable WorldPoint playerTile)
	{
		if (player != null && (targetActor == player || interacting == player))
		{
			return true;
		}
		if (target == null || playerTile == null || target.getPlane() != playerTile.getPlane())
		{
			return false;
		}
		int dx = Math.abs(target.getX() - playerTile.getX());
		int dy = Math.abs(target.getY() - playerTile.getY());
		return Math.max(dx, dy) <= 1;
	}

	/**
	 * The NPC whose projectile is landing now, when exactly one projectile matches.
	 */
	@Nullable
	Integer attackerIndex(int cycle)
	{
		prune(cycle);
		Seen match = null;
		int best = Integer.MAX_VALUE;
		boolean tie = false;
		for (Seen seen : recent)
		{
			int gap = seen.endCycle - cycle;
			if (gap > MATCH_AFTER || gap < -MATCH_BEFORE)
			{
				continue;
			}
			int distance = Math.abs(gap);
			if (distance < best)
			{
				best = distance;
				match = seen;
				tie = false;
			}
			else if (distance == best && match != null && !Objects.equals(seen.npcIndex, match.npcIndex))
			{
				tie = true;
			}
		}
		if (match == null || tie)
		{
			return null;
		}
		return match.npcIndex;
	}

	@Nullable
	CombatStyle styleFor(@Nullable Integer npcIndex, int cycle, @Nullable String name)
	{
		if (npcIndex == null)
		{
			return null;
		}
		prune(cycle);
		Seen match = closest(cycle, npcIndex);
		if (match == null)
		{
			match = closest(cycle, null);
		}
		if (match == null)
		{
			return CombatStyle.MELEE;
		}
		return projectileStyle(match.projectileId, name, match.magic);
	}

	/**
	 * Style of a projectile landing now when the attacker is not known yet.
	 * No projectile means the hit is not a spell.
	 */
	@Nullable
	CombatStyle landingStyle(int cycle, @Nullable String name)
	{
		prune(cycle);
		Seen match = closest(cycle, null);
		if (match == null)
		{
			return null;
		}
		return projectileStyle(match.projectileId, name, match.magic);
	}

	/**
	 * Known ranged projectiles stay ranged even when the monster also casts.
	 * Known magic projectiles, and projectiles from magic-only monsters, are magic.
	 */
	static CombatStyle projectileStyle(int projectileId, @Nullable String name, boolean markedMagic)
	{
		if (isMeleeProjectile(projectileId))
		{
			return CombatStyle.MELEE;
		}
		if (isRangedProjectile(projectileId))
		{
			return CombatStyle.RANGED;
		}
		if (markedMagic || isMagicProjectile(projectileId) || magicName(name))
		{
			return CombatStyle.MAGIC;
		}
		return CombatStyle.RANGED;
	}

	static boolean isMeleeProjectile(int projectileId)
	{
		return projectileId == SpotanimID.VFX_STANDARD_PROJECTILE_MELEE;
	}

	static boolean isMagicProjectile(int projectileId)
	{
		switch (projectileId)
		{
			case 393: // dragonfire
			case 395: // ice dragonfire
			case 1242: // Cerberus magic
			case 1247: // Cerberus fire
			case 1304: // demonic gorilla magic
			case 1339: // Olm magic
			case 1471: // Vorkath prayer disable
			case 1479: // Vorkath magic
			case 1606: // Sotetseg magic
			case 1637: // drake breath
			case 1662: // Hydra magic
			case 1664:
			case 1665: // Hydra lightning
			case 1707:
			case 1708: // Hunllef magic
			case 1713:
			case 1714: // Hunllef prayer
			case SpotanimID.VFX_STANDARD_PROJECTILE_MAGIC: // Doom magic orb
			case SpotanimID.VFX_ROCK_PROJECTILE_LAUNCH_MAGIC: // Doom rock, magic
			case SpotanimID.VFX_ROCK_PROJECTILE_SPLIT_MAGIC:
				return true;
			default:
				return false;
		}
	}

	static boolean isRangedProjectile(int projectileId)
	{
		switch (projectileId)
		{
			case 53: // cannonball
			case 1245: // Cerberus ranged
			case 1302: // demonic gorilla ranged
			case 1324: // ice demon ranged
			case 1329: // Vasa ranged
			case 1340: // Olm ranged
			case 1443: // granite cannonball
			case 1477: // Vorkath ranged
			case 1607: // Sotetseg ranged
			case 1663: // Hydra ranged
			case 1711:
			case 1712: // Hunllef ranged
			case SpotanimID.VFX_STANDARD_PROJECTILE_RANGE: // Doom ranged orb
			case SpotanimID.VFX_ROCK_PROJECTILE_LAUNCH_RANGE: // Doom rock, ranged
			case SpotanimID.VFX_ROCK_PROJECTILE_SPLIT_RANGE:
				return true;
			default:
				return false;
		}
	}

	@Nullable
	private Seen closest(int cycle, @Nullable Integer npcIndex)
	{
		Seen match = null;
		int best = Integer.MAX_VALUE;
		for (Seen seen : recent)
		{
			if (npcIndex != null && !npcIndex.equals(seen.npcIndex))
			{
				continue;
			}
			int gap = seen.endCycle - cycle;
			if (gap > MATCH_AFTER || gap < -MATCH_BEFORE)
			{
				continue;
			}
			int distance = Math.abs(gap);
			if (distance < best)
			{
				best = distance;
				match = seen;
			}
		}
		return match;
	}

	static boolean magicName(@Nullable String name)
	{
		if (name == null)
		{
			return false;
		}
		String lower = name.toLowerCase();
		return lower.contains("mage")
			|| lower.contains("wizard")
			|| lower.contains("spectre")
			|| lower.contains("bloodveld")
			|| lower.contains("dust devil")
			|| lower.contains("nechryael")
			|| lower.contains("jelly")
			|| lower.contains("banshee")
			|| lower.contains("smoke devil")
			|| lower.contains("kraken")
			|| lower.contains("dragon");
	}

	private void prune(int cycle)
	{
		dropOlderThan(recent, cycle);
		dropOlderThan(playerSpells, cycle);
	}

	private static void dropOlderThan(List<Seen> seen, int cycle)
	{
		Iterator<Seen> iterator = seen.iterator();
		while (iterator.hasNext())
		{
			if (cycle - iterator.next().endCycle > KEEP)
			{
				iterator.remove();
			}
		}
	}

	private static final class Seen
	{
		@Nullable
		private final Integer npcIndex;
		private final int endCycle;
		private int projectileId;
		private boolean magic;

		private Seen(@Nullable Integer npcIndex, int endCycle, int projectileId, boolean magic)
		{
			this.npcIndex = npcIndex;
			this.endCycle = endCycle;
			this.projectileId = projectileId;
			this.magic = magic;
		}
	}
}

