			// Araxxor eggs and the minions that hatch from them.
			NpcID.ARAXXOR_MINION_EGG_MIRRORBACK,
			NpcID.ARAXXOR_MINION_MIRRORBACK,
			NpcID.ARAXXOR_MINION_EGG_EXPLODE,
