package com.combatlog;

import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.SwingUtilities;
import net.runelite.client.game.SpriteManager;

/**
 * Offensive prayer sprites from the game cache, drawn beside the weapon.
 */
@Singleton
class PrayerIcons
{
	static final int SIZE = 24;

	private final SpriteManager spriteManager;
	private final ConcurrentHashMap<Integer, BufferedImage> icons = new ConcurrentHashMap<>();
	private final Set<Integer> pending = ConcurrentHashMap.newKeySet();
	private volatile Runnable onLoaded;

	@Inject
	PrayerIcons(SpriteManager spriteManager)
	{
		this.spriteManager = spriteManager;
	}

	void onLoaded(Runnable callback)
	{
		onLoaded = callback;
	}

	BufferedImage get(Integer spriteId)
	{
		if (spriteId == null || spriteId <= 0)
		{
			return null;
		}
		BufferedImage icon = icons.get(spriteId);
		if (icon != null || spriteManager == null || !pending.add(spriteId))
		{
			return icon;
		}
		spriteManager.getSpriteAsync(spriteId, 0, image -> finish(spriteId, image));
		return null;
	}

	private void finish(int spriteId, BufferedImage image)
	{
		try
		{
			if (image != null)
			{
				icons.put(spriteId, toIcon(image));
				Runnable callback = onLoaded;
				if (callback != null)
				{
					SwingUtilities.invokeLater(callback);
				}
			}
		}
		finally
		{
			pending.remove(spriteId);
		}
	}

	private static BufferedImage toIcon(BufferedImage source)
	{
		int width = source.getWidth();
		int height = source.getHeight();
		if (width <= 0 || height <= 0)
		{
			return source;
		}
		double scale = Math.min(SIZE / (double) width, SIZE / (double) height);
		if (scale > 1)
		{
			scale = 1;
		}
		int scaledWidth = Math.max(1, (int) Math.round(width * scale));
		int scaledHeight = Math.max(1, (int) Math.round(height * scale));
		BufferedImage icon = new BufferedImage(scaledWidth, scaledHeight, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = icon.createGraphics();
		graphics.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
		graphics.drawImage(source, 0, 0, scaledWidth, scaledHeight, null);
		graphics.dispose();
		return icon;
	}
}

package com.combatlog;

/**
 * Doom's melee-punish bonus is an extra hitsplat for each hit of the swing,
 * and that bonus grants no combat experience. The experience filter therefore
 * keeps a crystal halberd spec of 17+16 and throws away the 16 and 24 beside it.
 */
final class PunishHits
{
	private PunishHits()
	{
	}

	/**
	 * Puts back Doom bonus hitsplats the experience filter removed. Only an
	 * amount equal to {@code bonus} is the melee punish. A grub explosion, or
	 * another player's hit, stays dropped.
	 */
	static void restore(boolean[] keep, int[] amounts, int bonus, boolean[] eligible)
	{
		if (bonus <= 0)
		{
			return;
		}
		int slots = 0;
		for (int i = 0; i < amounts.length; i++)
		{
			if (eligible[i] && keep[i] && amounts[i] > 0)
			{
				slots++;
			}
		}
		int restored = 0;
		for (int i = 0; i < amounts.length && restored < slots; i++)
		{
			if (eligible[i] && !keep[i] && amounts[i] == bonus)
			{
				keep[i] = true;
				restored++;
			}
		}
	}
}

package com.combatlog;

import java.util.Objects;
import javax.annotation.Nullable;

/**
 * Marks your hitsplats that belong to a special attack. The spec follows the
 * swing, not whichever actor happened to be interacting when the energy
 * dropped. Hitsplats that were already waiting are left alone, and thrall,
 * vengeance, and burn splats are never claimed.
 */
public final class SpecMarker
{
	/** Ticks an armed spec waits for its hitsplats before it is dropped. */
	static final int SPEC_WINDOW = 10;

	@Nullable
	private Integer npcIndex;
	private int remaining;
	private int serial;
	private int armTick = -1;
	private int holdTicks = SPEC_WINDOW;

	public void arm(@Nullable Integer npcIndex, int weaponId, int tick)
	{
		this.npcIndex = npcIndex;
		this.remaining = SpecWeapons.splats(weaponId);
		this.serial++;
		this.armTick = tick;
		// Melee damage lands the tick after the swing. A zero hold dropped the
		// crystal halberd special before those hitsplats were classified.
		this.holdTicks = SpecWeapons.sameTick(weaponId) ? 1 : SPEC_WINDOW;
	}

	/**
	 * The attack animation is a better target than the actor from the energy
	 * drop. Only the swing that spent the spec can retarget it.
	 */
	public void retarget(@Nullable Integer npcIndex, int tick)
	{
		if (remaining <= 0 || npcIndex == null || armTick < 0 || tick < armTick || tick - armTick > 1)
		{
			return;
		}
		this.npcIndex = npcIndex;
	}

	/**
	 * Drops an armed spec whose hitsplats never arrived, such as a spec that
	 * missed entirely or hit a target that was not tracked.
	 */
	public void expire(int tick)
	{
		if (remaining > 0 && armTick >= 0 && tick - armTick > holdTicks)
		{
			remaining = 0;
		}
	}

	public void reset()
	{
		npcIndex = null;
		remaining = 0;
		armTick = -1;
		holdTicks = SPEC_WINDOW;
	}

	public int serial()
	{
		return remaining > 0 ? serial : 0;
	}

	/** The swing on this tick is the one that spent the special. */
	public boolean armedOn(int tick)
	{
		return remaining > 0 && armTick == tick;
	}

	public int reserved(@Nullable Integer npcIndex)
	{
		if (remaining <= 0 || !Objects.equals(this.npcIndex, npcIndex))
		{
			return 0;
		}
		return remaining;
	}

	public boolean claim(@Nullable Integer npcIndex, DamageDirection direction, DamageSource source, int hitSerial)
	{
		if (remaining <= 0 || hitSerial == 0 || hitSerial != serial || direction != DamageDirection.OUTGOING || source != DamageSource.WEAPON)
		{
			return false;
		}
		if (this.npcIndex != null && !Objects.equals(this.npcIndex, npcIndex))
		{
			return false;
		}
		if (this.npcIndex == null)
		{
			this.npcIndex = npcIndex;
		}
		remaining--;
		return true;
	}
}

package com.combatlog;

/**
 * How many of your hitsplats belong to one special attack.
 * Anything not listed marks the next hitsplat only.
 */
public final class SpecWeapons
{
	private SpecWeapons()
	{
	}

	public static int splats(int weaponId)
	{
		switch (weaponId)
		{
			case 1215: // dragon dagger
			case 1231:
			case 5680:
			case 5698:
			case 13265: // abyssal dagger
			case 13267:
			case 13269:
			case 13271:
				return 2;
			case 29577: // burning claws
			case 33200:
				return 3;
			case 13652: // dragon claws
			case 20784:
			case 26708:
			case 28039:
			case 28534:
				return 4;
			default:
				// The crystal halberd sweep can hit one large monster on two or three tiles.
				return crystalHalberd(weaponId) ? 3 : 1;
		}
	}

	/**
	 * The sweep's extra hitsplats land on the swing tick or the tick after it.
	 * Spare claims must be gone on the tick after that.
	 */
	public static boolean sameTick(int weaponId)
	{
		return crystalHalberd(weaponId);
	}

	private static boolean crystalHalberd(int weaponId)
	{
		return weaponId == 23987 // crystal halberd
			|| weaponId == 24125 // crystal halberd (2500)
			|| (weaponId >= 13080 && weaponId <= 13101);
	}

	/**
	 * How many ticks that weapon's extra hitsplats can lag behind the first.
	 * Zero means the swing is a single hitsplat.
	 */
	public static int burst(int weaponId)
	{
		int hits = splats(weaponId);
		if (hits >= 3)
		{
			return 2;
		}
		return hits > 1 ? 1 : 0;
	}

	/** The multi-hit is the special itself, rather than every swing. */
	public static boolean multiSpec(int weaponId)
	{
		return splats(weaponId) >= 3;
	}
}

package com.combatlog;

import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import javax.annotation.Nullable;

/**
 * Reads the equipped weapon's attack styles the same way the attack styles
 * plugin does. A splash is a missed spell, so melee and ranged misses stay
 * ordinary blocks.
 */
final class SpellStyle
{
	private SpellStyle()
	{
	}

	static boolean isCasting(@Nullable String styleName)
	{
		if (styleName == null)
		{
			return false;
		}
		switch (styleName.toUpperCase(Locale.ROOT))
		{
			case "CASTING":
			case "DEFENSIVE_CASTING":
				return true;
			default:
				return false;
		}
	}

	/**
	 * Styles used when the weapon-style enum has no entry. These match the
	 * attack styles plugin's fallback for the same weapon types.
	 */
	static String[] fallback(int weaponType)
	{
		if (weaponType == 22)
		{
			return new String[] {"ACCURATE", "AGGRESSIVE", null, "DEFENSIVE", "CASTING", "DEFENSIVE_CASTING"};
		}
		if (weaponType == 30)
		{
			return new String[] {"ACCURATE", "AGGRESSIVE", "AGGRESSIVE", "DEFENSIVE"};
		}
		return new String[0];
	}

	/**
	 * The style currently selected. Style index 4 is the spell slot, and the
	 * defensive-casting varbit picks the slot beside it. The sixth style is
	 * stored as defensive even when it casts.
	 */
	@Nullable
	static String selected(@Nullable String[] rawNames, int attackStyle, int defensiveCastingMode)
	{
		List<String> styles = new ArrayList<>();
		if (rawNames != null)
		{
			for (String name : rawNames)
			{
				if (name != null && name.equalsIgnoreCase("OTHER"))
				{
					continue;
				}
				styles.add(name);
			}
		}
		int index = attackStyle;
		if (index == 4)
		{
			index += Math.max(0, defensiveCastingMode);
		}
		if (index < 0 || index >= styles.size())
		{
			return null;
		}
		String name = styles.get(index);
		if (name != null && index == 5 && name.equalsIgnoreCase("DEFENSIVE"))
		{
			return "DEFENSIVE_CASTING";
		}
		return name;
	}

	static boolean rangedWeapon(@Nullable String[] rawNames)
	{
		if (rawNames == null)
		{
			return false;
		}
		for (String name : rawNames)
		{
			if (name == null)
			{
				continue;
			}
			switch (name.toUpperCase(Locale.ROOT))
			{
				case "RANGING":
				case "LONGRANGE":
					return true;
				default:
					break;
			}
		}
		return false;
	}

	/**
	 * A projectile is a spell when the player is casting, or when the weapon
	 * cannot shoot (a manual cast from a staff or a melee weapon). An unknown
	 * weapon is left alone so a ranged miss is not called a splash.
	 */
	static boolean spellProjectile(@Nullable String selectedStyle, @Nullable String[] styleNames)
	{
		if (isCasting(selectedStyle))
		{
			return true;
		}
		if (styleNames == null || styleNames.length == 0)
		{
			return false;
		}
		return !rangedWeapon(styleNames);
	}
}

