package com.combatlog;

import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.EnumMap;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.SwingUtilities;
import net.runelite.api.gameval.SpriteID;
import net.runelite.client.game.SpriteManager;

/**
 * The game's protect-from-melee, protect-from-missiles, and protect-from-magic
 * sprites. Those are the icons Old School RuneScape uses for the three styles.
 */
@Singleton
class StyleIcons
{
	static final int SIZE = 24;

	private final SpriteManager spriteManager;
	private final EnumMap<CombatStyle, BufferedImage> icons = new EnumMap<>(CombatStyle.class);
	private final Set<CombatStyle> pending = ConcurrentHashMap.newKeySet();
	private volatile Runnable onLoaded;

	@Inject
	StyleIcons(SpriteManager spriteManager)
	{
		this.spriteManager = spriteManager;
	}

	void onLoaded(Runnable callback)
	{
		onLoaded = callback;
	}

	BufferedImage get(CombatStyle style)
	{
		if (style == null)
		{
			return null;
		}
		BufferedImage icon = icons.get(style);
		if (icon != null || spriteManager == null || !pending.add(style))
		{
			return icon;
		}
		spriteManager.getSpriteAsync(spriteId(style), 0, image -> finish(style, image));
		return null;
	}

	private static int spriteId(CombatStyle style)
	{
		switch (style)
		{
			case RANGED:
				return SpriteID.Prayeron.PROTECT_FROM_MISSILES;
			case MAGIC:
				return SpriteID.Prayeron.PROTECT_FROM_MAGIC;
			default:
				return SpriteID.Prayeron.PROTECT_FROM_MELEE;
		}
	}

	private void finish(CombatStyle style, BufferedImage image)
	{
		try
		{
			if (image != null)
			{
				icons.put(style, toIcon(image));
				Runnable callback = onLoaded;
				if (callback != null)
				{
					SwingUtilities.invokeLater(callback);
				}
			}
		}
		finally
		{
			pending.remove(style);
		}
	}

	private static BufferedImage toIcon(BufferedImage source)
	{
		int width = source.getWidth();
		int height = source.getHeight();
		if (width <= 0 || height <= 0)
		{
			return source;
		}
		double scale = Math.min(SIZE / (double) width, SIZE / (double) height);
		if (scale > 1)
		{
			scale = 1;
		}
		int scaledWidth = Math.max(1, (int) Math.round(width * scale));
		int scaledHeight = Math.max(1, (int) Math.round(height * scale));
		BufferedImage icon = new BufferedImage(scaledWidth, scaledHeight, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = icon.createGraphics();
		graphics.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
		graphics.drawImage(source, 0, 0, scaledWidth, scaledHeight, null);
		graphics.dispose();
		return icon;
	}
}

package com.combatlog;

import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.game.ItemManager;
import net.runelite.client.util.AsyncBufferedImage;

/**
 * Outgoing, incoming, and both tab marks. The sprites are the dragon scimitar
 * and the rune kiteshield from the game cache.
 */
@Slf4j
@Singleton
class TabIcons
{
	static final int SCIMITAR = 4587;
	static final int KITE = 1201;
	static final int SIZE = 28;

	private final ItemManager itemManager;
	private final ConcurrentHashMap<Integer, BufferedImage> icons = new ConcurrentHashMap<>();
	private final Set<Integer> pending = ConcurrentHashMap.newKeySet();
	private volatile Runnable onLoaded;
	private volatile BufferedImage paired;

	@Inject
	TabIcons(ItemManager itemManager)
	{
		this.itemManager = itemManager;
	}

	void onLoaded(Runnable callback)
	{
		onLoaded = callback;
	}

	BufferedImage sword()
	{
		return get(SCIMITAR);
	}

	BufferedImage shield()
	{
		return get(KITE);
	}

	BufferedImage both()
	{
		BufferedImage cached = paired;
		if (cached != null)
		{
			return cached;
		}
		BufferedImage sword = sword();
		BufferedImage shield = shield();
		if (sword == null || shield == null)
		{
			return null;
		}
		int gap = 3;
		int width = sword.getWidth() + gap + shield.getWidth();
		int height = Math.max(sword.getHeight(), shield.getHeight());
		BufferedImage image = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = image.createGraphics();
		graphics.drawImage(sword, 0, (height - sword.getHeight()) / 2, null);
		graphics.drawImage(shield, sword.getWidth() + gap, (height - shield.getHeight()) / 2, null);
		graphics.dispose();
		paired = image;
		return image;
	}

	private BufferedImage get(int itemId)
	{
		BufferedImage icon = icons.get(itemId);
		if (icon != null || itemManager == null || !pending.add(itemId))
		{
			return icon;
		}
		try
		{
			AsyncBufferedImage image = itemManager.getImage(itemId);
			image.onLoaded(() -> finish(itemId, image));
		}
		catch (Exception ex)
		{
			pending.remove(itemId);
			log.debug("Could not request tab icon {}", itemId, ex);
		}
		return null;
	}

	private void finish(int itemId, BufferedImage image)
	{
		try
		{
			icons.put(itemId, toIcon(image));
			Runnable callback = onLoaded;
			if (callback != null)
			{
				SwingUtilities.invokeLater(callback);
			}
		}
		catch (Exception ex)
		{
			log.debug("Could not scale tab icon {}", itemId, ex);
		}
		finally
		{
			pending.remove(itemId);
		}
	}

	private static BufferedImage toIcon(BufferedImage source)
	{
		BufferedImage trimmed = trim(source);
		int width = trimmed.getWidth();
		int height = trimmed.getHeight();
		if (width <= 0 || height <= 0)
		{
			return source;
		}
		double scale = Math.min(SIZE / (double) width, SIZE / (double) height);
		int scaledWidth = Math.max(1, (int) Math.round(width * scale));
		int scaledHeight = Math.max(1, (int) Math.round(height * scale));
		BufferedImage icon = new BufferedImage(scaledWidth, scaledHeight, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = icon.createGraphics();
		graphics.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
		graphics.drawImage(trimmed, 0, 0, scaledWidth, scaledHeight, null);
		graphics.dispose();
		return icon;
	}

	private static BufferedImage trim(BufferedImage image)
	{
		int width = image.getWidth();
		int height = image.getHeight();
		int minX = width;
		int minY = height;
		int maxX = -1;
		int maxY = -1;
		for (int y = 0; y < height; y++)
		{
			for (int x = 0; x < width; x++)
			{
				if ((image.getRGB(x, y) >>> 24) > 16)
				{
					minX = Math.min(minX, x);
					minY = Math.min(minY, y);
					maxX = Math.max(maxX, x);
					maxY = Math.max(maxY, y);
				}
			}
		}
		if (maxX < minX || maxY < minY)
		{
			return image;
		}
		return image.getSubimage(minX, minY, maxX - minX + 1, maxY - minY + 1);
	}
}

