package com.combatlog;

import java.awt.image.BufferedImage;
import java.io.IOException;
import java.io.InputStream;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import javax.annotation.Nullable;
import javax.imageio.ImageIO;

/**
 * Thralls summoned with the Book of the Dead. Lesser thralls hit 0–1,
 * superior 0–2, and greater 0–3. The icon is that thrall's resurrect spell,
 * drawn in the weapon slot. The fallback is the greater ghostly thrall,
 * used only when a thrall hit was recorded without its NPC.
 */
final class Thralls
{
	static final int FALLBACK_NPC_ID = 10880;

	private static final Map<Integer, BufferedImage> ICONS = new ConcurrentHashMap<>();

	private Thralls()
	{
	}

	static int iconId(HitRecord hit)
	{
		Integer id = hit.getSourceNpcId();
		return id != null && id > 0 ? id : FALLBACK_NPC_ID;
	}

	/**
	 * The resurrect-spell picture for this hit, or the greater ghostly thrall
	 * when the NPC was not one of the nine thralls.
	 */
	@Nullable
	static BufferedImage image(HitRecord hit)
	{
		int id = iconId(hit);
		if (maxHit(id) <= 0)
		{
			id = FALLBACK_NPC_ID;
		}
		BufferedImage cached = ICONS.get(id);
		if (cached != null)
		{
			return cached;
		}
		BufferedImage loaded = read(id);
		if (loaded == null)
		{
			return null;
		}
		ICONS.put(id, loaded);
		return loaded;
	}

	static String name(int npcId)
	{
		switch (npcId)
		{
			case 10878:
				return "Lesser ghostly thrall";
			case 10879:
				return "Superior ghostly thrall";
			case 10880:
				return "Greater ghostly thrall";
			case 10881:
				return "Lesser skeletal thrall";
			case 10882:
				return "Superior skeletal thrall";
			case 10883:
				return "Greater skeletal thrall";
			case 10884:
				return "Lesser zombified thrall";
			case 10885:
				return "Superior zombified thrall";
			case 10886:
				return "Greater zombified thrall";
			default:
				return "Thrall";
		}
	}

	@Nullable
	private static BufferedImage read(int npcId)
	{
		try (InputStream in = Thralls.class.getResourceAsStream("/com/combatlog/thrall/" + npcId + ".png"))
		{
			if (in == null)
			{
				return null;
			}
			return ImageIO.read(in);
		}
		catch (IOException ex)
		{
			return null;
		}
	}

	/**
	 * Max hit of a known thrall NPC, or 0 when the id is not a thrall.
	 * Ghostly, skeletal, and zombified forms share a max per tier.
	 */
	static int maxHit(int npcId)
	{
		switch (npcId)
		{
			case 10878:
			case 10881:
			case 10884:
				return 1;
			case 10879:
			case 10882:
			case 10885:
				return 2;
			case 10880:
			case 10883:
			case 10886:
				return 3;
			default:
				return 0;
		}
	}

	/**
	 * Picks the one hitsplat that belongs to the thrall. Weapon slots are
	 * filled first, blocks first and then the largest hits, so a small hit
	 * left over inside the thrall's max is the thrall's damage.
	 *
	 * @return index into {@code amounts}, or -1
	 */
	static int pick(int[] amounts, boolean[] blocks, int weaponSlots, int thrallMax, boolean thrallSwung)
	{
		if (!thrallSwung || thrallMax <= 0 || amounts.length == 0)
		{
			return -1;
		}
		boolean[] reserved = new boolean[amounts.length];
		int slots = Math.max(0, weaponSlots);
		for (int i = 0; i < amounts.length && slots > 0; i++)
		{
			if (blocks[i])
			{
				reserved[i] = true;
				slots--;
			}
		}
		while (slots > 0)
		{
			int largest = -1;
			for (int i = 0; i < amounts.length; i++)
			{
				if (reserved[i])
				{
					continue;
				}
				if (largest < 0 || amounts[i] > amounts[largest])
				{
					largest = i;
				}
			}
			if (largest < 0)
			{
				break;
			}
			reserved[largest] = true;
			slots--;
		}
		int best = -1;
		for (int i = 0; i < amounts.length; i++)
		{
			if (reserved[i] || blocks[i] || amounts[i] < 1 || amounts[i] > thrallMax)
			{
				continue;
			}
			if (best < 0 || amounts[i] < amounts[best])
			{
				best = i;
			}
		}
		return best;
	}
}

package com.combatlog;

import java.util.Locale;
import javax.annotation.Nullable;
import net.runelite.api.gameval.SpriteID;

/**
 * Punch, kick, and block. Those are the three styles on the combat tab when
 * nothing is equipped, and their sprites are the fist, the boot, and the block.
 */
final class UnarmedStyle
{
	private UnarmedStyle()
	{
	}

	@Nullable
	static Integer icon(@Nullable String styleName)
	{
		if (styleName == null)
		{
			return null;
		}
		switch (styleName.toUpperCase(Locale.ROOT))
		{
			case "ACCURATE":
				return SpriteID.Combaticons.UNARMED_PUNCH;
			case "AGGRESSIVE":
				return SpriteID.Combaticons.UNARMED_KICK;
			case "DEFENSIVE":
			case "BLOCK":
				return SpriteID.Combaticons.UNARMED_BLOCK;
			default:
				return null;
		}
	}

	/**
	 * The selected unarmed style. The combat tab keeps an empty slot in front
	 * of Block, so Block is the style at that index, not the next name in a
	 * compacted list.
	 */
	@Nullable
	static Integer iconForStyles(@Nullable String[] rawNames, int attackStyleIndex)
	{
		String name = null;
		if (rawNames != null && attackStyleIndex >= 0 && attackStyleIndex < rawNames.length)
		{
			name = rawNames[attackStyleIndex];
			if (name != null && name.equalsIgnoreCase("OTHER"))
			{
				name = null;
			}
		}
		Integer icon = icon(name);
		if (icon != null)
		{
			return icon;
		}
		if (name != null)
		{
			return null;
		}
		return iconForIndex(attackStyleIndex);
	}

	/**
	 * Used when the style list cannot be read. Punch, kick, then block. Block
	 * also sits in the fourth combat-tab slot when the third slot is empty.
	 */
	@Nullable
	static Integer iconForIndex(int attackStyleIndex)
	{
		switch (attackStyleIndex)
		{
			case 0:
				return SpriteID.Combaticons.UNARMED_PUNCH;
			case 1:
				return SpriteID.Combaticons.UNARMED_KICK;
			case 2:
			case 3:
				return SpriteID.Combaticons.UNARMED_BLOCK;
			default:
				return null;
		}
	}

	@Nullable
	static String name(@Nullable Integer spriteId)
	{
		if (spriteId == null)
		{
			return null;
		}
		if (spriteId == SpriteID.Combaticons.UNARMED_PUNCH)
		{
			return "Punch";
		}
		if (spriteId == SpriteID.Combaticons.UNARMED_KICK)
		{
			return "Kick";
		}
		if (spriteId == SpriteID.Combaticons.UNARMED_BLOCK)
		{
			return "Block";
		}
		return null;
	}
}

package com.combatlog;

import java.util.List;

/**
 * Vengeance reflects 75% of the damage you took, rounded down. Matching a
 * hitsplat against what hit you that tick tells it apart from your own hits.
 */
final class Vengeance
{
	private Vengeance()
	{
	}

	/**
	 * Picks the first eligible hit equal to three quarters of an incoming hit.
	 *
	 * @return index into {@code amounts}, or -1
	 */
	static int pick(int[] amounts, boolean[] eligible, List<Integer> incoming)
	{
		for (int i = 0; i < amounts.length; i++)
		{
			if (!eligible[i] || amounts[i] <= 0)
			{
				continue;
			}
			for (int taken : incoming)
			{
				if (taken * 3 / 4 == amounts[i])
				{
					return i;
				}
			}
		}
		return -1;
	}
}

package com.combatlog;

import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.game.ItemManager;
import net.runelite.client.util.AsyncBufferedImage;

/**
 * Small transparent item icons for the weapon that landed each hit. Sprites
 * come from the game cache through {@link ItemManager} and are cached by item id.
 */
@Slf4j
@Singleton
class WeaponIcons
{
	static final int SIZE = 24;

	private final ItemManager itemManager;
	private final ConcurrentHashMap<Integer, BufferedImage> icons = new ConcurrentHashMap<>();
	private final Set<Integer> pending = ConcurrentHashMap.newKeySet();
	private volatile Runnable onLoaded;

	@Inject
	WeaponIcons(ItemManager itemManager)
	{
		this.itemManager = itemManager;
	}

	void onLoaded(Runnable callback)
	{
		onLoaded = callback;
	}

	BufferedImage get(int itemId)
	{
		if (itemId <= 0)
		{
			return null;
		}

		BufferedImage icon = icons.get(itemId);
		if (icon != null || !pending.add(itemId))
		{
			return icon;
		}

		try
		{
			AsyncBufferedImage image = itemManager.getImage(itemId);
			image.onLoaded(() -> finish(itemId, image));
		}
		catch (Exception | AssertionError ex)
		{
			pending.remove(itemId);
			log.debug("Could not request weapon icon {}", itemId, ex);
		}
		return null;
	}

	private void finish(int itemId, BufferedImage image)
	{
		try
		{
			icons.put(itemId, toIcon(image));
			Runnable callback = onLoaded;
			if (callback != null)
			{
				SwingUtilities.invokeLater(callback);
			}
		}
		catch (Exception ex)
		{
			log.debug("Could not scale weapon icon {}", itemId, ex);
		}
		finally
		{
			pending.remove(itemId);
		}
	}

	private static BufferedImage toIcon(BufferedImage source)
	{
		BufferedImage trimmed = trim(source);
		int width = trimmed.getWidth();
		int height = trimmed.getHeight();
		if (width <= 0 || height <= 0)
		{
			return source;
		}

		double scale = Math.min(SIZE / (double) width, SIZE / (double) height);
		int scaledWidth = Math.max(1, (int) Math.round(width * scale));
		int scaledHeight = Math.max(1, (int) Math.round(height * scale));
		BufferedImage icon = new BufferedImage(scaledWidth, scaledHeight, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = icon.createGraphics();
		graphics.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
		graphics.drawImage(trimmed, 0, 0, scaledWidth, scaledHeight, null);
		graphics.dispose();
		return icon;
	}

	private static BufferedImage trim(BufferedImage image)
	{
		int width = image.getWidth();
		int height = image.getHeight();
		int minX = width;
		int minY = height;
		int maxX = -1;
		int maxY = -1;
		for (int y = 0; y < height; y++)
		{
			for (int x = 0; x < width; x++)
			{
				if ((image.getRGB(x, y) >>> 24) > 16)
				{
					if (x < minX)
					{
						minX = x;
					}
					if (y < minY)
					{
						minY = y;
					}
					if (x > maxX)
					{
						maxX = x;
					}
					if (y > maxY)
					{
						maxY = y;
					}
				}
			}
		}
		if (maxX < minX || maxY < minY)
		{
			return image;
		}
		return image.getSubimage(minX, minY, maxX - minX + 1, maxY - minY + 1);
	}
}

package com.combatlog;

import javax.annotation.Nullable;
import net.runelite.api.Player;
import net.runelite.api.PlayerComposition;
import net.runelite.api.kit.KitType;

/**
 * The item in another player's weapon slot. {@link PlayerComposition#getEquipmentId}
 * is the client API for worn gear and already returns the item id, or -1 when
 * that slot is empty.
 */
final class WeaponSlot
{
	static final int UNARMED = 0;

	private WeaponSlot()
	{
	}

	/**
	 * @return the weapon item id, {@link #UNARMED} when the slot is empty, or
	 * null when the player model is not available
	 */
	@Nullable
	static Integer itemId(@Nullable Player player)
	{
		if (player == null)
		{
			return null;
		}
		PlayerComposition composition = player.getPlayerComposition();
		if (composition == null)
		{
			return null;
		}
		int id = composition.getEquipmentId(KitType.WEAPON);
		if (id <= 0)
		{
			return UNARMED;
		}
		return id;
	}
}

