	private static HitRecord hit(String name, int index, int amount, int tick)
	{
		return new HitRecord(tick * 1000L, name, TargetKind.NPC, 1, index, null, amount, HitKind.HIT, null, tick, DamageDirection.OUTGOING, DamageSource.WEAPON, false, 0, null, null, tick);
	}

	private static JLabel findTooltip(Component component, String tooltip)
	{
		if (component instanceof JLabel && tooltip.equals(((JLabel) component).getToolTipText()))
		{
			return (JLabel) component;
		}
		if (component instanceof java.awt.Container)
		{
			java.awt.Container container = (java.awt.Container) component;
			for (int i = 0; i < container.getComponentCount(); i++)
			{
				JLabel found = findTooltip(container.getComponent(i), tooltip);
				if (found != null)
				{
					return found;
				}
			}
		}
		return null;
	}

	private static void click(JLabel label)
	{
		label.dispatchEvent(new MouseEvent(label, MouseEvent.MOUSE_CLICKED, System.currentTimeMillis(), 0, 1, 1, 1, false, MouseEvent.BUTTON1));
	}

	private static JLabel findLabel(Component component, String text)
	{
		if (component instanceof JLabel && text.equals(((JLabel) component).getText()))
		{
			return (JLabel) component;
		}
		if (component instanceof java.awt.Container)
		{
			java.awt.Container container = (java.awt.Container) component;
			for (int i = 0; i < container.getComponentCount(); i++)
			{
				JLabel found = findLabel(container.getComponent(i), text);
				if (found != null)
				{
					return found;
				}
			}
		}
		return null;
	}

	private static int labelIndex(Component component, String text)
	{
		int[] index = {-1, 0};
		walkLabels(component, text, index);
		return index[0];
	}

	private static void walkLabels(Component component, String text, int[] index)
	{
		if (component instanceof JLabel && text.equals(((JLabel) component).getText()))
		{
			if (index[0] < 0)
			{
				index[0] = index[1];
			}
		}
		index[1]++;
		if (component instanceof java.awt.Container)
		{
			java.awt.Container container = (java.awt.Container) component;
			for (int i = 0; i < container.getComponentCount(); i++)
			{
				walkLabels(container.getComponent(i), text, index);
			}
		}
	}

	private static int countLabels(Component component, String text)
	{
		int count = component instanceof JLabel && text.equals(((JLabel) component).getText()) ? 1 : 0;
		if (component instanceof java.awt.Container)
		{
			java.awt.Container container = (java.awt.Container) component;
			for (int i = 0; i < container.getComponentCount(); i++)
			{
				count += countLabels(container.getComponent(i), text);
			}
		}
		return count;
	}

	private static JLabel findLabelContaining(Component component, String text)
	{
		if (component instanceof JLabel && ((JLabel) component).getText() != null
			&& ((JLabel) component).getText().contains(text))
		{
			return (JLabel) component;
		}
		if (component instanceof java.awt.Container)
		{
			java.awt.Container container = (java.awt.Container) component;
			for (int i = 0; i < container.getComponentCount(); i++)
			{
				JLabel found = findLabelContaining(container.getComponent(i), text);
				if (found != null)
				{
					return found;
				}
			}
		}
		return null;
	}

	private static JButton findButton(Component component, String text)
	{
		if (component instanceof JButton && text.equals(((JButton) component).getText()))
		{
			return (JButton) component;
		}
		if (component instanceof java.awt.Container)
		{
			java.awt.Container container = (java.awt.Container) component;
			for (int i = 0; i < container.getComponentCount(); i++)
			{
				JButton found = findButton(container.getComponent(i), text);
				if (found != null)
				{
					return found;
				}
			}
		}
		return null;
	}

	private static CombatLogConfig config()
	{
		return config(1);
	}

	private static CombatLogConfig config(int openFights)
	{
		return (CombatLogConfig) Proxy.newProxyInstance(
			CombatLogConfig.class.getClassLoader(),
			new Class[]{CombatLogConfig.class},
			(proxy, method, args) ->
			{
				if ("openFights".equals(method.getName()))
				{
					return Integer.valueOf(openFights);
				}
				if (method.getReturnType() == boolean.class)
				{
					return Boolean.TRUE;
				}
				if (method.getReturnType() == int.class)
				{
					return Integer.valueOf(10);
				}
				if (method.getReturnType() == String.class)
				{
					return "";
				}
				return null;
			});
	}

	@Test
	public void bothTotalsKeepTheLastDigitWithTheRest() throws Exception
	{
		Font font;
		try (InputStream in = FontManager.class.getResourceAsStream("runescape_bold.ttf"))
		{
			assertNotNull(in);
			font = Font.createFont(Font.TRUETYPE_FONT, in).deriveFont(Font.BOLD, 18f);
		}
		assertTrue(widestInkGap(paintAmount("162", font)) <= 3);
		assertTrue(widestInkGap(paintAmount("362", font)) <= 3);
		assertEquals(5, inkRuns(paintAmount("2,376", font)));
	}

	private static BufferedImage paintAmount(String text, Font font)
	{
		CombatLogPanel.TightAmount amount = new CombatLogPanel.TightAmount(text, font, Color.WHITE);
		Dimension size = amount.getPreferredSize();
		BufferedImage image = new BufferedImage(size.width, size.height, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = image.createGraphics();
		amount.setSize(size);
		amount.paint(graphics);
		graphics.dispose();
		return image;
	}

	private static int widestInkGap(BufferedImage image)
	{
		boolean[] ink = inkColumns(image);
		int worst = 0;
		int gap = 0;
		boolean seen = false;
		for (boolean column : ink)
		{
			if (column)
			{
				if (seen)
				{
					worst = Math.max(worst, gap);
				}
				seen = true;
				gap = 0;
			}
			else if (seen)
			{
				gap++;
			}
		}
		return worst;
	}

	private static int inkRuns(BufferedImage image)
	{
		boolean[] ink = inkColumns(image);
		int runs = 0;
		boolean on = false;
		for (boolean column : ink)
		{
			if (column && !on)
			{
				runs++;
			}
			on = column;
		}
		return runs;
	}

	private static boolean[] inkColumns(BufferedImage image)
	{
		boolean[] ink = new boolean[image.getWidth()];
		for (int x = 0; x < image.getWidth(); x++)
		{
			for (int y = 0; y < image.getHeight(); y++)
			{
				if (((image.getRGB(x, y) >>> 24) & 0xff) > 40)
				{
					ink[x] = true;
					break;
				}
			}
		}
		return ink;
	}

	private static boolean isDark(int rgb)
	{
		int red = (rgb >> 16) & 255;
		int green = (rgb >> 8) & 255;
		int blue = rgb & 255;
		return red < 80 && green < 80 && blue < 80;
	}

	private static JScrollPane scrollPane(CombatLogPanel panel)
	{
		return panel.wrappedScrollPane();
	}

	private static boolean contains(Component component, Class<?> type)
	{
		if (type.isInstance(component))
		{
			return true;
		}
		if (component instanceof java.awt.Container)
		{
			java.awt.Container container = (java.awt.Container) component;
			for (int i = 0; i < container.getComponentCount(); i++)
			{
				if (contains(container.getComponent(i), type))
				{
					return true;
				}
			}
		}
		return false;
	}
}

