		log.add(doomHit(11, 23987, 16, false));
		log.add(doomHit(11, 23987, 16, false).asSource(DamageSource.PUNISH, 23987, null));
		log.add(doomHit(11, 23987, 24, false).asSource(DamageSource.PUNISH, 23987, null));

		List<AttackRow> rows = AttackRow.group(log.summarize(20_000L, 20).getFights().get(0).visibleHits(DamageView.OUTGOING));
		assertEquals(2, rows.size());
		assertEquals("Dealt", CombatLogFormatter.rowKind(rows.get(0)));
		assertEquals("(Punish) (16+24) 40", CombatLogFormatter.rowAmount(rows.get(0)));
		assertEquals("Spec", CombatLogFormatter.rowKind(rows.get(1)));
		assertEquals("(17+16) 33", CombatLogFormatter.rowAmount(rows.get(1)));
		assertTrue(HitStyle.othersDamage(HitsplatID.DAMAGE_OTHER));
		assertNull(HitStyle.fromHitsplatType(HitsplatID.DAMAGE_OTHER));
	}

	@Test
	public void grubExplosionIsNotLoggedAsPunish()
	{
		// The spec is 12. The 99 and 100 are grubs exploding on the shield, and 15 is the bonus.
		int[] amounts = {12, 99, 100, 15};
		boolean[] keep = OwnHits.keep(amounts, 12 * 4, false, false);
		assertNotNull(keep);
		assertTrue(keep[0]);
		assertFalse(keep[1]);
		assertFalse(keep[2]);
		assertFalse(keep[3]);
		PunishHits.restore(keep, amounts, 15, new boolean[] {true, true, true, true});
		assertTrue(keep[0]);
		assertFalse(keep[1]);
		assertFalse(keep[2]);
		assertTrue(keep[3]);
	}

	@Test
	public void gemstoneCrabKeepsTheBlowpipeHitAndDropsAnotherPlayersMax()
	{
		// 20 damage on the crab is 70 ranged experience. A 54 beside it is not yours.
		int[] amounts = {20, 54};
		boolean[] keep = OwnHits.keep(amounts, 70, true, false);
		assertNotNull(keep);
		assertTrue(keep[0]);
		assertFalse(keep[1]);
		PunishHits.restore(keep, amounts, 24, new boolean[] {false, false});
		assertTrue(keep[0]);
		assertFalse(keep[1]);

		int[] mixed = {17, 16, 54};
		boolean[] mixedKeep = OwnHits.keep(mixed, 33 * 4, false, false);
		assertNotNull(mixedKeep);
		assertTrue(mixedKeep[0]);
		assertTrue(mixedKeep[1]);
		assertFalse(mixedKeep[2]);
		PunishHits.restore(mixedKeep, mixed, 24, new boolean[] {true, true, false});
		assertTrue(mixedKeep[0]);
		assertTrue(mixedKeep[1]);
		assertFalse(mixedKeep[2]);

		HitRecord max = new HitRecord(1_000L, "Gemstone Crab", TargetKind.NPC, NpcID.GEMSTONE_CRAB, 4, 12926, 20, HitKind.MAX_HIT, null);
		assertEquals("20 (Max hit)", CombatLogFormatter.rowAmount(AttackRow.group(Collections.singletonList(max)).get(0)));
	}

	@Test
	public void experienceIdentifiesYourHitsWhenOtherPlayersHitTheSameTick()
	{
		boolean[] normal = OwnHits.keep(new int[] {12, 14, 10, 54}, 144, false, false);
		assertNotNull(normal);
		assertTrue(normal[0]);
		assertTrue(normal[1]);
		assertTrue(normal[2]);
		assertFalse(normal[3]);

		boolean[] single = OwnHits.keep(new int[] {20, 8, 12}, 80, false, false);
		assertNotNull(single);
		assertTrue(single[0]);
		assertFalse(single[1]);
		assertFalse(single[2]);

		assertNull(OwnHits.keep(new int[] {54, 0}, 0, true, false));
		assertNull(OwnHits.keep(new int[] {54, 0}, 0, false, false));

		// 11 damage is 38.5 experience, reported as 38 or 39.
		boolean[] odd = OwnHits.keep(new int[] {11, 54}, 39, true, false);
		assertNotNull(odd);
		assertTrue(odd[0]);
		assertFalse(odd[1]);
		boolean[] oddLow = OwnHits.keep(new int[] {54, 11}, 38, true, false);
		assertNotNull(oddLow);
		assertFalse(oddLow[0]);
		assertTrue(oddLow[1]);

		assertNull(OwnHits.keep(new int[] {20}, 65, false, true));
		assertNull(OwnHits.keep(new int[] {54}, 70, true, false));
	}

	private static HitRecord specHit(int tick, int weapon, int amount, boolean block)
	{
		return new HitRecord(tick * 600L, "Zezima", TargetKind.PLAYER, null, null, weapon, amount, block ? HitKind.BLOCK : HitKind.HIT, null, tick, DamageDirection.INCOMING, DamageSource.WEAPON, false, 0, null, 4L, tick);
	}

	private static HitRecord attackHit(int tick, int amount, long attackId)
	{
		return new HitRecord(tick * 600L, "Goblin", TargetKind.NPC, 301, 4, 1333, amount, HitKind.HIT, null, tick, DamageDirection.OUTGOING, DamageSource.WEAPON, false, 0, attackId, null, 0);
	}

	private static HitRecord hit(long time, String name, TargetKind kind, int amount, HitKind hitKind)
	{
		return hit(time, name, kind, null, amount, hitKind);
	}

	private static HitRecord hit(long time, String name, TargetKind kind, Integer npcIndex, int amount, HitKind hitKind)
	{
		return new HitRecord(time, name, kind, null, npcIndex, null, amount, hitKind, null);
	}
}

package com.combatlog;

import java.awt.Color;
import java.awt.image.BufferedImage;
import java.util.Collections;
import net.runelite.api.gameval.SpriteID;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotSame;
import static org.junit.Assert.assertTrue;

public class GameHitsplatsTest
{
	@Test
	public void damageBlockAndStatusUseCacheSprites()
	{
		assertEquals(SpriteID.Hitmark._1, GameHitsplats.spriteFor(hit(HitKind.HIT, null, DamageSource.WEAPON)));
		assertEquals(SpriteID.Hitmark.HITSPLAT_BLUE_MISS, GameHitsplats.spriteFor(hit(HitKind.BLOCK, null, DamageSource.WEAPON)));
		assertEquals(SpriteID.Hitmark.HITSPLAT_BLUE_MISS, GameHitsplats.spriteFor(hit(HitKind.SPLASH, null, DamageSource.WEAPON)));
		assertEquals(SpriteID.Hitmark.HITSPLAT_GREEN_POISON, GameHitsplats.spriteFor(hit(HitKind.HIT, null, DamageSource.POISON)));
		assertEquals(SpriteID.Hitmark.HITSPLAT_DARK_GREEN_VENOM, GameHitsplats.spriteFor(hit(HitKind.HIT, null, DamageSource.VENOM)));
		assertEquals(SpriteID.Hitmark.BURN_DAMAGE, GameHitsplats.spriteFor(hit(HitKind.HIT, null, DamageSource.BURN)));
		assertEquals(SpriteID.Hitmark.COLOSSEUM_DOOM, GameHitsplats.spriteFor(hit(HitKind.HIT, null, DamageSource.DOOM)));
		assertEquals(SpriteID.Hitmark._3, GameHitsplats.spriteFor(hit(HitKind.HIT, null, DamageSource.DISEASE)));
		assertEquals(SpriteID.Hitmark._6, GameHitsplats.spriteFor(hit(HitKind.HIT, "Cyan", DamageSource.WEAPON)));
		assertEquals(SpriteID.Hitmark._1, GameHitsplats.spriteFor(hit(HitKind.MAX_HIT, null, DamageSource.WEAPON)));
	}

	@Test
	public void digitsStayOnACopyOfTheSplat()
	{
		HitRecord hit = hit(HitKind.HIT, null, DamageSource.WEAPON);
		AttackRow row = AttackRow.group(Collections.singletonList(hit)).get(0);
		assertEquals("32", GameHitsplats.digits(row));

		BufferedImage background = new BufferedImage(24, 23, BufferedImage.TYPE_INT_ARGB);
		int red = new Color(180, 0, 0).getRGB();
		for (int y = 0; y < background.getHeight(); y++)
		{
			for (int x = 0; x < background.getWidth(); x++)
			{
				background.setRGB(x, y, red);
			}
		}
		BufferedImage stamped = GameHitsplats.stamp(background, "32");
		assertNotSame(background, stamped);
		assertEquals(red, background.getRGB(12, 11));
		assertTrue(hasLightPixel(stamped));
	}

	private static boolean hasLightPixel(BufferedImage image)
	{
		for (int y = 0; y < image.getHeight(); y++)
		{
			for (int x = 0; x < image.getWidth(); x++)
			{
				int rgb = image.getRGB(x, y);
				int r = (rgb >> 16) & 0xff;
				int g = (rgb >> 8) & 0xff;
				int b = rgb & 0xff;
				if (r > 220 && g > 220 && b > 220)
				{
					return true;
				}
			}
		}
		return false;
	}

	private static HitRecord hit(HitKind kind, String tint, DamageSource source)
	{
		return new HitRecord(1_000L, "Goblin", TargetKind.NPC, 1, 1, 1333, 32, kind, tint, 4, DamageDirection.OUTGOING, source, false, 0, null, null, 1);
	}
}

